// hooks.ts — Entry point for dev-team hooks (protect-files, record-files, static-check)

import { readFileSync } from 'node:fs';
import * as path from 'node:path';

import { runStaticAnalysis } from './commands/run-static-analysis';
import { getChangeDir } from './lib/change';
import { readConfig } from './lib/config';
import {
  type FileOp,
  foldFileOps,
  readFileInventory,
  writeFileInventory,
} from './lib/file-inventory';
import { matchGlob } from './lib/glob';
import { getProjectDir } from './lib/project-root';
import { bindSession, lookupChange } from './lib/session-registry';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface ProtectedPattern {
  glob: string;
  reason?: string;
}

interface ProtectionResult {
  matched: boolean;
  matchedGlob?: string;
  reason?: string;
}

// ---------------------------------------------------------------------------
// Type Guards
// ---------------------------------------------------------------------------

/**
 * Type guard: value is a non-null, non-array object.
 * Allows safe narrowing from `unknown` to `Record<string, unknown>`.
 */
function isRecord(value: unknown): value is Record<string, unknown> {
  return value != null && typeof value === 'object' && !Array.isArray(value);
}

// ---------------------------------------------------------------------------
// Pattern Loading
// ---------------------------------------------------------------------------

/**
 * Load and merge patterns from built-in defaults and user configuration.
 * User patterns come from openspec/config.json `write_protection.files`,
 * validated through the Zod schema via readConfig().
 */
function loadPatterns(projectRoot: string): ProtectedPattern[] {
  const patterns: ProtectedPattern[] = [];

  // Add built-in patterns inline to ensure perTest coverage analysis
  // attributes mutations on these strings to each calling test
  patterns.push({
    glob: '**/openspec/changes/**/workflow.json',
    reason:
      '该文件受写入保护：%s。detected via %t。请使用 phase_log / backtrack / change_create MCP 工具替代。',
  });
  patterns.push({
    glob: '**/openspec/config.json',
    reason: '该文件受写入保护：%s。detected via %t。请提供修改方案，通知用户自行操作。',
  });

  const config = readConfig(projectRoot);
  const files = config.write_protection?.files ?? [];
  for (const file of files) {
    if (!file.glob) {
      continue;
    }
    patterns.push({
      glob: path.isAbsolute(file.glob) ? file.glob : `**/${file.glob}`,
      reason: file.reason,
    });
  }

  return patterns;
}

// ---------------------------------------------------------------------------
// Path Protection Check
// ---------------------------------------------------------------------------

/**
 * Check a file path against an array of ProtectedPattern.
 * Returns the matched result or { matched: false }.
 * Uses matchGlob (picomatch) for glob matching — no hand-written globToRegex.
 *
 * @internal Exported for testing only.
 */
function isProtected(filePath: string, patterns: ProtectedPattern[]): ProtectionResult {
  if (!filePath) return { matched: false };
  const normalized = filePath.replace(/\\/g, '/');

  for (const p of patterns) {
    if (matchGlob(normalized, p.glob)) {
      return {
        matched: true,
        matchedGlob: p.glob,
        reason: p.reason,
      };
    }
  }

  return { matched: false };
}

// ---------------------------------------------------------------------------
// Deny Reason Builder
// ---------------------------------------------------------------------------

/**
 * Build a human-readable deny reason.
 * If the pattern has a custom reason, use it with %s (file path) and %t (tool name) substitution.
 * Otherwise use a generic fallback message.
 *
 * @internal Exported for testing only.
 */
function buildDenyReason(
  pattern: ProtectionResult | null,
  filePath: string,
  toolName: string,
): string {
  if (pattern && pattern.reason) {
    return pattern.reason.replace(/%s/g, filePath).replace(/%t/g, toolName);
  }
  return `该文件受写入保护：${filePath}。detected via ${toolName}。`;
}

/**
 * Deny reason for bulk-restore / bulk-clean commands: they rewrite the
 * workspace wholesale and are invisible to the file recorder, so they are
 * denied instead of recorded.
 */
function buildBulkRevertDenyReason(toolName: string, detail: string): string {
  return (
    `该命令被拦截（detected via ${toolName}）：${detail}。` +
    '批量还原/清理对文件清单记录器不可见；请改用逐路径 git restore <path>（可被记录并折叠为净 untouched）。'
  );
}

// ---------------------------------------------------------------------------
// Argument Tokenizing
// ---------------------------------------------------------------------------

/** Split a command-argument string into whitespace tokens with quotes stripped. */
function tokenize(args: string): string[] {
  return args
    .split(/\s+/)
    .filter(Boolean)
    .map((t) => t.replace(/^['"]|['"]$/g, ''))
    .filter(Boolean);
}

/** True for option tokens ( `-f`, `-rf`, `--cached` ). */
function isFlag(token: string): boolean {
  return token.startsWith('-');
}

/**
 * Scan `command <args>` occurrences for the given command names.
 * The argument string stops at a command separator (`;`, `|`, `&`) or newline.
 */
function scanCommand(cmd: string, names: string): Array<{ args: string }> {
  const results: Array<{ args: string }> = [];
  const re = new RegExp(`(?:^|[\\s;&|(])(?:${names})\\s+([^;&|\\n]*)`, 'gi');
  re.lastIndex = 0;
  let m: RegExpExecArray | null;
  while ((m = re.exec(cmd)) !== null) {
    results.push({ args: m[1] });
  }
  return results;
}

// ---------------------------------------------------------------------------
// Git Working-Tree Op Extraction
// ---------------------------------------------------------------------------

/**
 * Extract file ops from git subcommands that touch working-tree paths:
 * - `git restore <paths>` (no source) → revert; with `--source=<commit>`
 *   (or `-s <commit>`) → write;
 * - `git checkout -- <paths>` → revert; `git checkout <commit> -- <paths>` → write;
 * - `git rm <paths>` → delete (`git rm` also hits the generic delete commands below;
 *   folding deduplicates).
 *
 * `git stash` / `git clean` are PreToolUse bulk-revert concerns only — the
 * recorder never sees them (they are denied).
 */
function extractGitOps(cmd: string): FileOp[] {
  const ops: FileOp[] = [];
  const re = /\bgit\s+(restore|checkout|rm)\b([^\n;&|]*)/gi;
  re.lastIndex = 0;
  let m: RegExpExecArray | null;
  while ((m = re.exec(cmd)) !== null) {
    const sub = m[1].toLowerCase();
    const tokens = tokenize(m[2]);

    if (sub === 'rm') {
      for (const t of tokens) {
        if (!isFlag(t)) ops.push({ op: 'delete', path: t });
      }
      continue;
    }

    if (sub === 'restore') {
      let fromSource = false;
      const paths: string[] = [];
      for (let i = 0; i < tokens.length; i++) {
        const t = tokens[i];
        if (t.startsWith('--source=') || t === '-s') {
          fromSource = true;
          if (t === '-s') i++; // separate value form: skip the commit-ish
          continue;
        }
        if (isFlag(t)) continue;
        paths.push(t);
      }
      for (const p of paths) {
        ops.push({ op: fromSource ? 'write' : 'revert', path: p });
      }
      continue;
    }

    // checkout: only the path-restoring forms (with `--`) are recognized
    const sep = tokens.indexOf('--');
    if (sep === -1) continue;
    const commitish = tokens.slice(0, sep).filter((t) => !isFlag(t));
    const fromSource = commitish.length > 0;
    for (const p of tokens.slice(sep + 1).filter((t) => !isFlag(t))) {
      ops.push({ op: fromSource ? 'write' : 'revert', path: p });
    }
  }
  return ops;
}

// ---------------------------------------------------------------------------
// extractFileOps — three-state extractor shared by PreToolUse and PostToolUse
// ---------------------------------------------------------------------------

/** Write ops from bash redirections (existing regex set preserved). */
function extractBashRedirectWriteOps(cmd: string): FileOp[] {
  const ops: FileOp[] = [];
  const writeRegexes: readonly RegExp[] = [
    // > and >> redirect (not preceded by - or part of ->)
    /(?:^|[^-])>{1,2}\s+['"]?([^\s;|`$&()'"]+)['"]?/g,
    // >| redirect (noclobber override)
    />\|\s+['"]?([^\s;|`$&()'"]+)['"]?/g,
    // tee (possibly with -a or other flags)
    /(?:^|[\s;|&(])\s*tee\s+(?:-[a-zA-Z]+\s+)?['"]?([^\s;|`$&()'"]+)['"]?/g,
    // >& redirect
    />&\s*['"]?([^\s;|`$&()'"]+)['"]?/g,
  ];
  for (const re of writeRegexes) {
    re.lastIndex = 0;
    let m: RegExpExecArray | null;
    while ((m = re.exec(cmd)) !== null) {
      ops.push({ op: 'write', path: m[1] });
    }
  }
  return ops;
}

/** Write ops from PowerShell redirects, file-writing cmdlets and .NET methods. */
function extractPowerShellWriteOps(cmd: string): FileOp[] {
  const ops: FileOp[] = [];
  let m: RegExpExecArray | null;

  // Redirect operators: >, >>, *>, 1>, 2>, etc.
  const psRedirect = /(?:^|[\s;|&(])(?:\d*|\*)?>{1,2}\s+['"]?([^\s;|`$&()'",=]+)['"]?/g;
  while ((m = psRedirect.exec(cmd)) !== null) {
    ops.push({ op: 'write', path: m[1] });
  }

  const cmdlets = [
    'Set-Content',
    'Out-File',
    'Add-Content',
    'Export-Csv',
    'Export-CliXml',
    'Tee-Object',
  ];
  for (const cmdlet of cmdlets) {
    const re = new RegExp(
      `\\b${cmdlet}\\s+(?:-(?:Path|FilePath)\\s+)?['"]?([^\\s;\`$&()'",=]+)['"]?`,
      'gi',
    );
    while ((m = re.exec(cmd)) !== null) {
      ops.push({ op: 'write', path: m[1] });
    }
  }

  const dotnetMethods = ['WriteAllText', 'WriteAllLines', 'WriteAllBytes', 'AppendAllText'];
  for (const method of dotnetMethods) {
    const re = new RegExp(
      `\\[System\\.IO\\.File\\]::${method}\\s*\\(\\s*['"]?([^,;\\)'"]+)['"]?`,
      'gi',
    );
    while ((m = re.exec(cmd)) !== null) {
      ops.push({ op: 'write', path: m[1] });
    }
  }
  return ops;
}

/**
 * Delete ops from per-path delete commands (flags skipped). `git rm` is
 * covered by the `rm` match; folding deduplicates.
 */
function extractDeleteOps(cmd: string): FileOp[] {
  const ops: FileOp[] = [];
  for (const { args } of scanCommand(cmd, 'Remove-Item|rmdir|unlink|rm|del|rd')) {
    for (const t of tokenize(args)) {
      if (!isFlag(t)) ops.push({ op: 'delete', path: t });
    }
  }
  return ops;
}

/** Move ops: two-argument form → delete(old) + write(new) double entry. */
function extractMoveOps(cmd: string): FileOp[] {
  const ops: FileOp[] = [];
  for (const { args } of scanCommand(cmd, 'Move-Item|Rename-Item|ren|mv')) {
    const paths = tokenize(args).filter((t) => !isFlag(t));
    if (paths.length === 2) {
      ops.push({ op: 'delete', path: paths[0] });
      ops.push({ op: 'write', path: paths[1] });
    }
  }
  return ops;
}

/**
 * Extract file operations from a shell command (bash and PowerShell dialects
 * in one pass) as write / delete / revert ops:
 *
 * - write: `>` / `>>` / `>|` / `tee` / `>&`, PowerShell redirects and file-writing
 *   cmdlets (Set-Content / Out-File / Add-Content / Export-Csv / Export-CliXml /
 *   Tee-Object), `[System.IO.File]::WriteAll*`, `git restore --source=<commit>`,
 *   `git checkout <commit> -- <paths>`;
 * - delete: `rm` / `git rm` / `rmdir` / `unlink`, PowerShell `Remove-Item` / `del` / `rd`
 *   (per-path arguments, `-` flags skipped);
 * - delete(old) + write(new) double entry: two-argument `mv` / `Move-Item` /
 *   `ren` / `Rename-Item`;
 * - revert: `git restore <paths>` (no source), `git checkout -- <paths>`.
 *
 * Over-recording direction is safe: unknown long tails are reconciled by the
 * evaluator and the `change_files` tool. No python/node exemption here — the
 * exemption is a PreToolUse protection concern applied by the check functions.
 */
function extractFileOps(cmd: string): FileOp[] {
  return [
    ...extractBashRedirectWriteOps(cmd),
    ...extractPowerShellWriteOps(cmd),
    ...extractDeleteOps(cmd),
    ...extractMoveOps(cmd),
    ...extractGitOps(cmd),
  ];
}

// ---------------------------------------------------------------------------
// Shell Command Checks
// ---------------------------------------------------------------------------

/** Directory globs for the bulk-revert interception rules. */
const OPENSPEC_GLOB = '**/openspec/**';
const OPENSPEC_CHANGES_GLOB = '**/openspec/changes/**';

/**
 * Deny when an extracted write/delete path matches a protected glob.
 * Revert ops are not denied here — they are the sanctioned undo action,
 * recorded by the PostToolUse recorder (openspec workflow artifacts are
 * handled by checkBulkRevert).
 */
function checkExtractedOps(
  cmd: string,
  patterns: ProtectedPattern[],
  toolName: string,
): string | null {
  for (const op of extractFileOps(cmd)) {
    if (op.op === 'revert') continue;
    const result = isProtected(op.path, patterns);
    if (result.matched) {
      return buildDenyReason(result, op.path, toolName);
    }
  }
  return null;
}

/**
 * Intercept bulk restore/clean commands that rewrite the workspace wholesale
 * and are invisible to the file recorder:
 * - `git stash` (bare / push / pop / apply / branch) → deny; `list` / `show` → allow;
 * - `git clean` without path arguments, or with any path hitting `openspec/**`
 *   → deny; `-n` / `--dry-run` → allow;
 * - `git restore` / `git checkout --` targeting `openspec/changes/**` workflow
 *   artifacts → deny; source-code targets → allow (recorded as revert).
 */
function checkBulkRevert(cmd: string, toolName: string): string | null {
  const stashRe = /\bgit\s+stash\b([^\n;&|]*)/gi;
  stashRe.lastIndex = 0;
  let m: RegExpExecArray | null;
  while ((m = stashRe.exec(cmd)) !== null) {
    const args = m[1].trim();
    if (!/^(list|show)\b/.test(args)) {
      return buildBulkRevertDenyReason(toolName, 'git stash 会批量改写工作区');
    }
  }

  const cleanRe = /\bgit\s+clean\b([^\n;&|]*)/gi;
  cleanRe.lastIndex = 0;
  while ((m = cleanRe.exec(cmd)) !== null) {
    const tokens = tokenize(m[1]);
    const isDryRun = tokens.some((t) => t === '--dry-run' || /^-[^-]*n/.test(t));
    if (isDryRun) continue;
    const paths = tokens.filter((t) => !isFlag(t));
    const hitsOpenspec =
      paths.length === 0 || paths.some((p) => matchGlob(p.replace(/\\/g, '/'), OPENSPEC_GLOB));
    if (hitsOpenspec) {
      return buildBulkRevertDenyReason(toolName, 'git clean 会批量删除文件');
    }
  }

  for (const op of extractGitOps(cmd)) {
    if (op.op === 'revert' && matchGlob(op.path.replace(/\\/g, '/'), OPENSPEC_CHANGES_GLOB)) {
      return buildBulkRevertDenyReason(
        toolName,
        `git restore 不允许作用于 openspec/changes/** 工作流产物: ${op.path}`,
      );
    }
  }

  return null;
}

/**
 * Shared shell-command check: python/node exemption → extracted-path
 * protection (write + delete) → bulk-revert interception.
 */
function checkShellCommand(
  cmd: string,
  patterns: ProtectedPattern[],
  toolName: string,
): string | null {
  const normalized = cmd.replace(/\\/g, '/');

  // Exempt python/node script runners
  if (/^(python|python3|node)\s/.test(normalized)) return null;

  return checkExtractedOps(normalized, patterns, toolName) ?? checkBulkRevert(normalized, toolName);
}

/**
 * Check whether a bash command attempts to write to or delete a protected file.
 * Returns a deny reason string if protected, or null if the command is allowed.
 */
function checkBashCommand(cmd: string, patterns: ProtectedPattern[]): string | null {
  return checkShellCommand(cmd, patterns, 'Bash');
}

/**
 * Check whether a PowerShell command attempts to write to or delete a
 * protected file. Returns a deny reason string if protected, or null if the
 * command is allowed.
 */
function checkPowerShellCommand(cmd: string, patterns: ProtectedPattern[]): string | null {
  return checkShellCommand(cmd, patterns, 'PowerShell');
}

// ---------------------------------------------------------------------------
// Protected Path Matching
// ---------------------------------------------------------------------------

/**
 * Check a single file path against protected patterns.
 * Returns the deny reason if the path matches a protected pattern, or null.
 */
function matchProtectedPath(
  filePath: string,
  patterns: ProtectedPattern[],
  toolName: string,
): string | null {
  const result = isProtected(filePath, patterns);
  return result.matched ? buildDenyReason(result, filePath, toolName) : null;
}

// ---------------------------------------------------------------------------
// Tool Access Evaluation
// ---------------------------------------------------------------------------

/**
 * Evaluate whether a hook event's tool invocation is allowed to access
 * protected files.
 *
 * Parses the stdin JSON, routes to the appropriate checker based on tool_name,
 * and returns a deny reason string or null (fail-open).
 */
function evaluateToolAccess(raw: string, patterns: ProtectedPattern[]): string | null {
  if (!raw || !raw.trim()) return null;

  let parsed: Record<string, unknown>;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return null;
  }

  const toolName = parsed.tool_name;
  if (!toolName || typeof toolName !== 'string') return null;

  const toolInput = isRecord(parsed.tool_input) ? parsed.tool_input : undefined;

  if (toolName === 'Write' || toolName === 'Edit' || toolName === 'StrReplace') {
    const filePath = toolInput?.file_path;
    if (!filePath || typeof filePath !== 'string') return null;
    return matchProtectedPath(filePath, patterns, toolName);
  }

  if (toolName === 'Shell') {
    const command = toolInput?.command;
    if (!command || typeof command !== 'string') return null;
    return checkBashCommand(command, patterns) ?? checkPowerShellCommand(command, patterns);
  }

  if (toolName === 'Bash') {
    const command = toolInput?.command;
    if (!command || typeof command !== 'string') return null;
    return checkBashCommand(command, patterns);
  }

  if (toolName === 'PowerShell') {
    const command = toolInput?.command;
    if (!command || typeof command !== 'string') return null;
    return checkPowerShellCommand(command, patterns);
  }

  return null;
}

// ---------------------------------------------------------------------------
// Hook Response Output
// ---------------------------------------------------------------------------

/** Write allow/deny hook response JSON to stdout. */
function writeHookResponse(denyReason: string | null): void {
  if (denyReason !== null) {
    process.stdout.write(
      `${JSON.stringify({
        hookSpecificOutput: {
          hookEventName: 'PreToolUse',
          permissionDecision: 'deny',
          permissionDecisionReason: denyReason,
        },
      })}\n`,
    );
  } else {
    process.stdout.write(
      `${JSON.stringify({
        hookSpecificOutput: {
          hookEventName: 'PreToolUse',
          permissionDecision: 'allow',
        },
      })}\n`,
    );
  }
}

// ---------------------------------------------------------------------------
// protect-files subcommand
// ---------------------------------------------------------------------------

/**
 * protect-files subcommand entry point.
 *
 * Reads PreToolUse event JSON from stdin, loads protection patterns,
 * checks the tool invocation, and outputs allow/deny JSON to stdout.
 */
export function runProtectFiles(): void {
  const patterns = loadPatterns(getProjectDir());
  const denyReason = evaluateToolAccess(readFileSync(0, 'utf-8'), patterns);
  writeHookResponse(denyReason);
}

// ---------------------------------------------------------------------------
// record-files subcommand (PostToolUse file inventory recorder)
// ---------------------------------------------------------------------------

/** True for the MCP phase_next call event (matcher MUST use the full MCP tool name). */
function isPhaseNextCall(toolName: string): boolean {
  return toolName.startsWith('mcp__') && toolName.endsWith('phase_next');
}

/**
 * Extract raw file ops from a PostToolUse event's tool input:
 * Write/Edit → `file_path`, NotebookEdit → `notebook_path`,
 * Bash/PowerShell → `extractFileOps(command)`. Unknown tools yield no ops.
 */
function extractOpsFromToolInput(
  toolName: string,
  toolInput: Record<string, unknown> | undefined,
): FileOp[] {
  if (!toolInput) return [];

  if (toolName === 'Write' || toolName === 'Edit') {
    const filePath = toolInput.file_path;
    return typeof filePath === 'string' && filePath ? [{ op: 'write', path: filePath }] : [];
  }

  if (toolName === 'NotebookEdit') {
    const notebookPath = toolInput.notebook_path;
    return typeof notebookPath === 'string' && notebookPath
      ? [{ op: 'write', path: notebookPath }]
      : [];
  }

  if (toolName === 'Bash' || toolName === 'PowerShell') {
    const command = toolInput.command;
    if (typeof command !== 'string') return [];
    return extractFileOps(command.replace(/\\/g, '/'));
  }

  return [];
}

/**
 * Convert an extracted path to a project-root-relative POSIX path.
 * Returns null when the path resolves outside the project root (event dropped).
 */
function normalizeRecordedPath(inputPath: string, projectRoot: string): string | null {
  if (!inputPath) return null;
  const abs = path.isAbsolute(inputPath)
    ? path.resolve(inputPath)
    : path.resolve(projectRoot, inputPath);
  const rel = path.relative(projectRoot, abs);
  if (!rel || rel.startsWith('..') || path.isAbsolute(rel)) return null;
  return rel.replace(/\\/g, '/');
}

/**
 * Self-pollution exclusion: `openspec/**` workflow artifacts (proposal /
 * design / reports / architecture models) and `workflow.json` itself never
 * enter the inventory.
 */
function isExcludedFromInventory(relPath: string): boolean {
  return (
    relPath === 'openspec' ||
    relPath.startsWith('openspec/') ||
    relPath === 'workflow.json' ||
    relPath.endsWith('/workflow.json')
  );
}

/**
 * Bind `session_id → change` from a `phase_next` MCP call event. The binding
 * refreshes on every agent turn's `phase_next` call, so a lost registry
 * self-heals at the cost of one turn's recording window.
 */
function bindFromPhaseNextCall(
  projectRoot: string,
  sessionId: string | undefined,
  toolInput: Record<string, unknown> | undefined,
): void {
  const change = toolInput?.change;
  if (sessionId && typeof change === 'string' && change) {
    bindSession(projectRoot, sessionId, change);
  }
}

/**
 * Normalize, filter (self-pollution exclusion + project-root guard) and stamp
 * the event's `agent_type` onto the extracted ops.
 */
function collectRecordedOps(
  ops: FileOp[],
  projectRoot: string,
  agentType: string | undefined,
): FileOp[] {
  const recorded: FileOp[] = [];
  for (const op of ops) {
    const rel = normalizeRecordedPath(op.path, projectRoot);
    if (!rel || isExcludedFromInventory(rel)) continue;
    const entry: FileOp = { op: op.op, path: rel };
    if (agentType !== undefined) {
      entry.agentType = agentType;
    }
    recorded.push(entry);
  }
  return recorded;
}

/**
 * Attribute one PostToolUse event to the session-bound change.
 *
 * Flow: a `phase_next` MCP call event binds `session_id → change` (from
 * `tool_input.change`) and records nothing; every other event looks up the
 * binding, extracts paths, filters self-pollution and out-of-root targets,
 * folds the ops into the inventory net state and writes `workflow.json`.
 */
function recordFilesEvent(stdinRaw: string): void {
  if (!stdinRaw || !stdinRaw.trim()) return;

  let parsed: unknown;
  try {
    parsed = JSON.parse(stdinRaw);
  } catch {
    return;
  }
  if (!isRecord(parsed)) return;

  const toolName = parsed.tool_name;
  if (typeof toolName !== 'string' || !toolName) return;
  const toolInput = isRecord(parsed.tool_input) ? parsed.tool_input : undefined;
  const sessionId = typeof parsed.session_id === 'string' ? parsed.session_id : undefined;
  const agentType = typeof parsed.agent_type === 'string' ? parsed.agent_type : undefined;

  const projectRoot = getProjectDir();

  if (isPhaseNextCall(toolName)) {
    bindFromPhaseNextCall(projectRoot, sessionId, toolInput);
    return;
  }

  if (!sessionId) return;
  const change = lookupChange(projectRoot, sessionId);
  if (!change) {
    process.stderr.write(
      `record-files: session ${sessionId} 未绑定 change，丢弃 ${toolName} 事件\n`,
    );
    return;
  }

  const ops = extractOpsFromToolInput(toolName, toolInput);
  const recorded = collectRecordedOps(ops, projectRoot, agentType);
  if (recorded.length === 0) return;

  const changeDir = getChangeDir(change, projectRoot);
  // A legacy change (no `files`) throws here — swallowed by runRecordFiles'
  // catch-all (stderr diagnostic, exit 0); the change must be recreated.
  const inventory = readFileInventory(changeDir);
  writeFileInventory(changeDir, foldFileOps(inventory, recorded));
}

/**
 * record-files subcommand entry point (PostToolUse recorder).
 *
 * Any error — unbound session, unreadable stdin, legacy change without
 * `files` — is written to stderr only and the process exits 0: recording
 * MUST NOT block the observed tool call.
 */
export function runRecordFiles(): void {
  let stdinRaw: string;
  try {
    stdinRaw = readFileSync(0, 'utf-8');
  } catch {
    return;
  }
  try {
    recordFilesEvent(stdinRaw);
  } catch (e: unknown) {
    const message = e instanceof Error ? e.message : String(e);
    process.stderr.write(`record-files: ${message}\n`);
  }
}

// ---------------------------------------------------------------------------
// Stderr Capture
// ---------------------------------------------------------------------------

/**
 * Temporarily replace process.stderr.write to collect output.
 *
 * Returns a tuple [getCaptured, restore]:
 *   - getCaptured(): returns all stderr text collected so far
 *   - restore(): restores the original process.stderr.write
 *
 * Used by runStaticCheck to capture runStaticAnalysis output without
 * letting it leak to the real stderr.
 */
export function captureStderr(): [getCaptured: () => string, restore: () => void] {
  const chunks: string[] = [];
  const origWrite = process.stderr.write.bind(process.stderr);

  // The type assertion is necessary because the replacement function's
  // simplified signature doesn't match the full overloaded Writable type.
  process.stderr.write = ((chunk: string | Uint8Array): boolean => {
    chunks.push(typeof chunk === 'string' ? chunk : Buffer.from(chunk).toString());
    return true;
  }) as typeof process.stderr.write;

  function restore(): void {
    process.stderr.write = origWrite;
  }

  return [() => chunks.join(''), restore];
}

// ---------------------------------------------------------------------------
// static-check subcommand
// ---------------------------------------------------------------------------

const FOLLOWUP_PREFIX = '静态检查未通过，请修复以下错误后重新提交：\n\n';

/**
 * Parse workspace root from SubagentStop event JSON.
 *
 * Internal logic is written as a two-step check (extract first element,
 * then type-check) rather than a single compound condition, which makes
 * Stryker boundary/logical mutations individually killable.
 */
function parseWorkspaceRoot(stdinRaw: string): string | null {
  try {
    const parsed: Record<string, unknown> = JSON.parse(stdinRaw);
    const roots = parsed.workspace_roots;
    const firstRoot: unknown = Array.isArray(roots) && roots.length > 0 ? roots[0] : undefined;
    if (typeof firstRoot === 'string') {
      return path.posix.join(...firstRoot.split(path.sep));
    }
  } catch {
    // ignore JSON parse errors
  }
  return null;
}

/**
 * static-check subcommand entry point.
 *
 * Reads SubagentStop event JSON from stdin, extracts workspace root,
 * calls runStaticAnalysis in-process (no spawnSync), captures stderr
 * output, and formats the result.
 */
export function runStaticCheck(): void {
  const stdinRaw = readFileSync(0, 'utf-8');
  const workspaceRoot = parseWorkspaceRoot(stdinRaw);
  const projectRoot = workspaceRoot || getProjectDir();

  const [getCaptured, restore] = captureStderr();
  let exitCode: number;
  try {
    exitCode = runStaticAnalysis({ projectRoot });
  } finally {
    restore();
  }

  if (exitCode === 0) {
    process.stdout.write('{}\n');
    return;
  }

  const captured = getCaptured();
  const reason = FOLLOWUP_PREFIX + captured;
  process.stdout.write(
    `${JSON.stringify({ decision: 'block', reason, followup_message: reason })}\n`,
  );
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

/**
 * Top-level entry function.
 * Parses process.argv[2] as the subcommand name and dispatches.
 */
export function main(): void {
  const subcommand = process.argv[2];

  switch (subcommand) {
    case 'protect-files':
      runProtectFiles();
      break;
    case 'record-files':
      runRecordFiles();
      break;
    case 'static-check':
      runStaticCheck();
      break;
    default: {
      process.stderr.write(`Unknown subcommand: ${subcommand}\n`);
      process.exit(1);
    }
  }
}

// Execute main with a catch-all for unexpected errors.
// Outputs { decision: "block", reason: <error message> } on crash per design risk mitigation.
try {
  main();
} catch (error: unknown) {
  const message = error instanceof Error ? error.message : String(error);
  process.stdout.write(`${JSON.stringify({ decision: 'block', reason: message })}\n`);
  process.exit(1);
}

