type AgentType = 'claude' | 'cursor' | 'zcode';
export type ProductEnvKey = 'claude' | 'cursor' | 'cursorHome' | 'zcode';
type ProductLayout = 'plugin' | 'home-image';

export interface ProductEnv extends ModelEnv, ToolEnv {
  /** 适配agent */
  agent: AgentType;
  /** 产物形态 */
  layout: ProductLayout;
  /** 插件前缀 */
  pluginPrefix: string;
  /** 文件或工具名称的前缀，避免名称重复 */
  namePrefix: string;
  /** agent唤起mcp工具的前缀 */
  mcpToolPrefix: string;
  /** 产物目录 */
  outDir: string;
  /** 插件配置文件路径，（文件通常叫plugin.json) */
  pluginFilePath: string;
  /** hooks文件相对路径 */
  hooksFilePath: string;
  /** mcp文件相对路径 */
  mcpFilePath: string;
  /** 插件根目录 / cursor home目录 */
  pluginRoot: string;
}

interface ModelEnv {
  modelHigh: string;
  modelFast: string;
}

interface ToolEnv {
  toolWrite: string;
  toolEdit: string;
  toolBash: string;
  toolCmd: string;
  toolAskUser: string;
}

const PLUGIN_NAME = 'dev-team';

