      // 非标准库导入被解析, target 'service_b' 可能被匹配或产生 warning
      // 主要验证不 crash, 以及 os/sys 等不被计入
      expect(result.unmatched_files).not.toContain('src/service_a/main.py');
    } finally {
      cleanup();
    }
  });
});

