/**
 * 集成测试: mutation-scope-inventory
 *
 * 验证 AC-7 的端到端链路: --change CLI 参数 → 清单突变 scope → 净归零去噪。
 * git 仓库 fixture 与 workflow.json 全部真实(不 mock),只 mock 测试执行边界
 * (runTestDetectFrameworks / executePlanEntry / generateSubReport /
 * generateSummaryReport),用真实 HEAD 内容裁判去噪漏斗方向(只向 overstate、不漏删)。
 *
 * @see openspec/changes/workflow-file-inventory/test-design.md — 集成测试
 */

import { execFileSync } from 'node:child_process';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';

import { afterEach, beforeEach, describe, expect, it, vi, type Mock } from 'vite-plus/test';

import { runTestExecution } from '../../src/commands/test-execution';
import type { ExecutionResult } from '../../src/lib/test-runner';
import { type TestPlan } from '../../src/schemas';
import type {
  SourceFileEntry,
  TestExecutionSubReport,
} from '../../src/schemas/test-execution-output.schema';

// ---------------------------------------------------------------------------
// Mocks — 只隔离测试执行边界;git 与文件清单走真实实现
// ---------------------------------------------------------------------------

const mockExecutePlanEntry = vi.fn();
const mockGenerateSubReport = vi.fn();
const mockGenerateSummaryReport = vi.fn();
const mockRunTestDetectFrameworks = vi.fn();

vi.mock('../../src/lib/test-runner', () => ({
  executePlanEntry: (...args: unknown[]) => mockExecutePlanEntry(...args),
}));

vi.mock('../../src/lib/test-report', () => ({
  generateSubReport: (...args: unknown[]) => mockGenerateSubReport(...args),
  generateSummaryReport: (...args: unknown[]) => mockGenerateSummaryReport(...args),
}));

vi.mock('../../src/commands/test-detect-frameworks', () => ({
  runTestDetectFrameworks: (...args: unknown[]) => mockRunTestDetectFrameworks(...args),
}));

// ---------------------------------------------------------------------------
// Helpers(形状与 src/commands/test-execution.test.ts 保持一致)
// ---------------------------------------------------------------------------

function sfe(file: string, overrides: Partial<SourceFileEntry['coverage']> = {}): SourceFileEntry {
  return {
    file,
    coverage: {
      lines: 0,
      branches: null,
      functions: null,
      total_lines: null,
      covered_lines: null,
      total_branches: null,
      covered_branches: null,
      total_functions: null,
      covered_functions: null,
      ...overrides,
    },
  };
}

function makePlanEntry(overrides: Partial<TestPlan> = {}): TestPlan {
  return {
    cwd: '.',
    root: '.',
    framework: 'vitest',
    coverage_format: 'istanbul',
    coverage_output: 'coverage-summary.json',
    mutation_cwd: '.',
    mutation_script: null,
    script: {
      shell: '#!/bin/bash\nset -e\n\nnpx vitest run --coverage --coverage.reporter=json-summary',
      cmd: 'npx vitest run --coverage --coverage.reporter=json-summary',
    },
    ...overrides,
  };
}

function makeExecutionResult(overrides: Partial<ExecutionResult> = {}): ExecutionResult {
  return {
    framework: 'vitest',
    exitCode: 0,
    testCases: [{ name: 'test1', status: 'passed', durationMs: 100 }],
    coverage: null,
    mutation: null,
    durationMs: 500,
    testFiles: ['src/foo.test.ts'],
    sourceFiles: ['src/foo.ts'],
    planId: 'vitest',
    reportDir: '/tmp/reports/test/vitest',
    ...overrides,
  };
}

function makeSubReport(overrides: Partial<TestExecutionSubReport> = {}): TestExecutionSubReport {
  return {
    framework: 'vitest',
    root: '.',
    timestamp: '2026-09-17T00:00:00.000Z',
    exit_code: 0,
    duration_ms: 500,
    summary: { total: 1, passed: 1, failed: 0, skipped: 0 },
    error_cases: [],
    test_files: ['src/foo.test.ts'],
    source_files: [sfe('src/foo.ts')],
    coverage: null,
    mutation: null,
    ...overrides,
  };
}

function makeSummaryReport(): Record<string, unknown> {
  return {
    phase: 'test-execution',
    command: 'dev-team test-execution',
    timestamp: '2026-09-17T00:00:00.000Z',
    duration_seconds: 1,
    total: 1,
    passed: 1,
    failed: 0,
    skipped: 0,
    conclusion: 'pass',
    problems: [],
    coverage: null,
  };
}

interface GitProject {
  root: string;
  cleanup: () => void;
}

function runGit(cwd: string, args: string[]): void {
  execFileSync('git', args, { cwd, stdio: 'ignore' });
}

/** 真实 git 仓库 fixture:首次提交含 src/kept.ts 与 src/noisy.ts。 */
function createGitProject(): GitProject {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'mutation-scope-inventory-'));
  fs.mkdirSync(path.join(root, 'src'), { recursive: true });
  runGit(root, ['init']);
  runGit(root, ['config', 'user.email', 'test@example.com']);
  runGit(root, ['config', 'user.name', 'test']);
  // 字节级保真:禁止 autocrlf 改写行尾,保证 CRLF 用例的 HEAD 对比按原字节进行
  runGit(root, ['config', 'core.autocrlf', 'false']);
  runGit(root, ['config', 'commit.gpgsign', 'false']);
  fs.writeFileSync(path.join(root, 'src', 'kept.ts'), 'export const kept = 1;\n', 'utf-8');
  fs.writeFileSync(path.join(root, 'src', 'noisy.ts'), 'export const noisy = 1;\n', 'utf-8');
  runGit(root, ['add', '-A']);
  runGit(root, ['commit', '-m', 'init']);
  return { root, cleanup: () => fs.rmSync(root, { recursive: true, force: true }) };
}

/** 直接写 change 的 workflow.json;files 缺省时构造机制前旧 change。 */
function writeWorkflowJson(
  root: string,
  change: string,
  files?: { written: string[]; deleted: string[] },
): void {
  const changeDir = path.join(root, 'openspec', 'changes', change);
  fs.mkdirSync(changeDir, { recursive: true });
  const doc: Record<string, unknown> = { workflow_type: 'requirement', created: '2026-09-17' };
  if (files !== undefined) {
    doc.files = files;
  }
  fs.writeFileSync(
    path.join(changeDir, 'workflow.json'),
    `${JSON.stringify(doc, null, 2)}\n`,
    'utf-8',
  );
}

function abs(root: string, rel: string): string {
  return path.resolve(root, rel).replace(/\\/g, '/');
}

/** executePlanEntry 收到的 options.mutationDiffFiles。 */
function mutationDiffFilesPassed(): string[] | undefined {
  return mockExecutePlanEntry.mock.calls[0][2].mutationDiffFiles as string[] | undefined;
}

function stubHappyRun(): void {
  mockRunTestDetectFrameworks.mockReturnValue({ detected: [], plan: [makePlanEntry()] });
  mockExecutePlanEntry.mockReturnValue(makeExecutionResult());
  mockGenerateSubReport.mockReturnValue(makeSubReport());
  mockGenerateSummaryReport.mockReturnValue(makeSummaryReport());
}

// ---------------------------------------------------------------------------
// 场景: 真实仓库去噪漏斗
// ---------------------------------------------------------------------------

describe('场景: 真实仓库去噪漏斗', () => {
  let logs: string[] = [];
  let logSpy: Mock;

  beforeEach(() => {
    mockExecutePlanEntry.mockReset();
    mockGenerateSubReport.mockReset();
    mockGenerateSummaryReport.mockReset();
    mockRunTestDetectFrameworks.mockReset();
    logs = [];
    logSpy = vi.spyOn(console, 'log').mockImplementation((...args: unknown[]) => {
      logs.push(args.map(String).join(' '));
    });
  });

  afterEach(() => {
    logSpy.mockRestore();
  });

  it('正向: scope 恰为改写文件与 HEAD 缺席的新文件,net-zero 文件被剔除 (AC-7)', async () => {
    const project = createGitProject();
    try {
      writeWorkflowJson(project.root, 'inv', {
        written: ['src/kept.ts', 'src/noisy.ts', 'src/new-file.ts'],
        deleted: [],
      });
      // 工作区改写 kept.ts (≠ HEAD);noisy.ts 保持与 HEAD 一致;new-file.ts 不落盘
      fs.writeFileSync(
        path.join(project.root, 'src', 'kept.ts'),
        'export const kept = 2;\n',
        'utf-8',
      );
      stubHappyRun();

      const exitCode = await runTestExecution({ projectRoot: project.root, change: 'inv' });

      expect(exitCode).toBe(0);
      expect(mockExecutePlanEntry).toHaveBeenCalledTimes(1);
      const received = mutationDiffFilesPassed();
      expect(received).toHaveLength(2);
      expect([...received!].sort()).toEqual(
        [abs(project.root, 'src/kept.ts'), abs(project.root, 'src/new-file.ts')].sort(),
      );
      expect(received).not.toContain(abs(project.root, 'src/noisy.ts'));
      // 诊断行改为清单来源前缀,git diff 前缀退场
      expect(logs.some((l) => l.startsWith('mutation scope (change inventory): 2 files'))).toBe(
        true,
      );
      expect(logs.some((l) => l.startsWith('mutation denoise: 1 net-zero files excluded'))).toBe(
        true,
      );
      expect(logs.some((l) => l.startsWith('--mutation-diff-only:'))).toBe(false);
    } finally {
      project.cleanup();
    }
  });

  it('边界: written 全部与 HEAD 内容一致 → 空 scope 不报错,突变按空 scope 处理 (AC-7)', async () => {
    const project = createGitProject();
    try {
      writeWorkflowJson(project.root, 'inv', {
        written: ['src/kept.ts', 'src/noisy.ts'],
        deleted: [],
      });
      stubHappyRun();

      const exitCode = await runTestExecution({ projectRoot: project.root, change: 'inv' });

      expect(exitCode).toBe(0);
      expect(mockExecutePlanEntry).toHaveBeenCalledTimes(1);
      expect(mutationDiffFilesPassed()).toEqual([]);
    } finally {
      project.cleanup();
    }
  });

  it('边界: CRLF 行尾与反斜杠路径形态归一化后参与去噪漏斗 (AC-7)', async () => {
    const project = createGitProject();
    try {
      fs.writeFileSync(path.join(project.root, 'src', 'crlf.ts'), 'a\r\nb\r\n', 'utf-8');
      fs.writeFileSync(
        path.join(project.root, 'src', 'win.ts'),
        'export const win = 1;\n',
        'utf-8',
      );
      runGit(project.root, ['add', '-A']);
      runGit(project.root, ['commit', '-m', 'crlf and win']);
      // 提交后仅改写 win.ts;crlf.ts 工作区字节与 HEAD 完全一致(净归零 → 去噪命中)
      fs.writeFileSync(
        path.join(project.root, 'src', 'win.ts'),
        'export const win = 2;\n',
        'utf-8',
      );
      writeWorkflowJson(project.root, 'inv', {
        written: ['src/crlf.ts', 'src\\win.ts'],
        deleted: [],
      });
      stubHappyRun();

      const exitCode = await runTestExecution({ projectRoot: project.root, change: 'inv' });

      expect(exitCode).toBe(0);
      const received = mutationDiffFilesPassed();
      // crlf.ts 工作区字节 == HEAD → 去噪命中被剔除
      expect(received).not.toContain(abs(project.root, 'src/crlf.ts'));
      // 反斜杠拼写的 win.ts 工作区 ≠ HEAD → 保留,不因路径形态失效
      expect(received).toContain(abs(project.root, 'src/win.ts'));
      expect(received).toHaveLength(1);
    } finally {
      project.cleanup();
    }
  });
});

// ---------------------------------------------------------------------------
// 场景: 入口与守卫
// ---------------------------------------------------------------------------

describe('场景: 入口与守卫', () => {
  let logs: string[] = [];
  let logSpy: Mock;

  beforeEach(() => {
    mockExecutePlanEntry.mockReset();
    mockGenerateSubReport.mockReset();
    mockGenerateSummaryReport.mockReset();
    mockRunTestDetectFrameworks.mockReset();
    logs = [];
    logSpy = vi.spyOn(console, 'log').mockImplementation((...args: unknown[]) => {
      logs.push(args.map(String).join(' '));
    });
  });

  afterEach(() => {
    logSpy.mockRestore();
  });

  it('异常: 机制前旧 change (无 files) 传 change → 硬报错"请重建"且不产出执行报告 (AC-7)', async () => {
    const project = createGitProject();
    try {
      writeWorkflowJson(project.root, 'legacy');
      stubHappyRun();

      await expect(
        runTestExecution({ projectRoot: project.root, change: 'legacy' }),
      ).rejects.toThrow(/请重建/);

      expect(mockExecutePlanEntry).not.toHaveBeenCalled();
      expect(mockGenerateSummaryReport).not.toHaveBeenCalled();
    } finally {
      project.cleanup();
    }
  });

  it('正向: noMutation 与 change 同传 → 惰性解析,旧 change 不误报且不限圈 (AC-7)', async () => {
    const project = createGitProject();
    try {
      writeWorkflowJson(project.root, 'legacy');
      stubHappyRun();

      const exitCode = await runTestExecution({
        projectRoot: project.root,
        change: 'legacy',
        noMutation: true,
      });

      expect(exitCode).toBe(0);
      expect(mockExecutePlanEntry).toHaveBeenCalledTimes(1);
      expect(mutationDiffFilesPassed()).toBeUndefined();
      // 清单通道未激活:无 scope 诊断行
      expect(logs.some((l) => l.startsWith('mutation scope (change inventory):'))).toBe(false);
    } finally {
      project.cleanup();
    }
  });

  it('边界: 不传 change → 突变不限圈,清单通道完全不激活 (AC-7)', async () => {
    const project = createGitProject(); // fixture 不含 openspec/workflow.json
    try {
      stubHappyRun();

      const exitCode = await runTestExecution({ projectRoot: project.root });

      expect(exitCode).toBe(0);
      expect(mockExecutePlanEntry).toHaveBeenCalledTimes(1);
      expect(mutationDiffFilesPassed()).toBeUndefined();
    } finally {
      project.cleanup();
    }
  });

  it('正向: written 含测试文件路径 → 反推同位源文件并入 scope (AC-7)', async () => {
    const project = createGitProject();
    try {
      // foo.test.ts 与反推出的 foo.ts 均不在磁盘且不在 HEAD → 双双保留(overstate 方向)
      writeWorkflowJson(project.root, 'inv', { written: ['src/foo.test.ts'], deleted: [] });
      stubHappyRun();

      const exitCode = await runTestExecution({ projectRoot: project.root, change: 'inv' });

      expect(exitCode).toBe(0);
      const received = mutationDiffFilesPassed();
      expect(received).toHaveLength(2);
      expect(received).toContain(abs(project.root, 'src/foo.test.ts'));
      expect(received).toContain(abs(project.root, 'src/foo.ts'));
    } finally {
      project.cleanup();
    }
  });
});

build/assemble.test.ts.source:
/**
 * 单元测试: assemble.ts — 多平台产物组装
 *
 * 每个用例都在临时目录中自行生成 assemble 所需的源码树（含 .pack-staging
 * 构建产物），不读取仓库中的任何文件，因此不依赖先执行 pnpm build。
 */

import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';

import { afterEach, beforeEach, describe, expect, it, vi, type Mock } from 'vite-plus/test';

import * as envMod from './env';

const tempRoots: string[] = [];
let outBase = '';
let cwdSpy: Mock | undefined;

function mockCwd(root: string): void {
  cwdSpy?.mockRestore();
  cwdSpy = vi.spyOn(process, 'cwd').mockReturnValue(root);
}

function makeTempRoot(prefix: string): string {
  const root = mkdtempSync(join(tmpdir(), prefix));
  tempRoots.push(root);
  return root;
}

function makeOutDir(key: envMod.ProductEnvKey): string {
  const dir = join(outBase, key);
  mkdirSync(dir, { recursive: true });
  return dir;
}

vi.mock('./env', async (importOriginal) => {
  const actual = await importOriginal<typeof envMod>();
  return {
    ...actual,
    getEnv: (key: envMod.ProductEnvKey) => ({
      ...actual.getEnv(key),
      outDir: makeOutDir(key),
    }),
  };
});

const { assembleAll } = await import('./assemble');

function writeFixtureFile(root: string, rel: string, content: string): void {
  const full = join(root, rel);
  mkdirSync(dirname(full), { recursive: true });
  writeFileSync(full, content, 'utf-8');
}

/** canonical hooks：一条两端通用的 preToolUse，一条仅 claude 生效的 subagentStop。 */
const CANONICAL_HOOKS = {
  preToolUse: [
    {
      matchers: { claude: 'Write', cursor: 'Write' },
      commandTemplate: 'node "__DEV_TEAM_ROOT__/bin/__BIN:hooks__" protect-files',
    },
  ],
  subagentStop: [
    {
      matchers: { claude: '__CALL_AGENT:implementation-generator__', cursor: null },
      loop_limit: 5,
      commandTemplate: 'node "__DEV_TEAM_ROOT__/bin/__BIN:hooks__" static-check',
    },
  ],
};

/** 在 root 下生成 assemble 会从 cwd 读取的全部源码（含 .pack-staging 构建产物）。 */
function seedSourceTree(root: string): void {
  writeFixtureFile(root, 'hooks/hooks.canonical.json', JSON.stringify(CANONICAL_HOOKS, null, 2));
  writeFixtureFile(root, '.pack-staging/bin/cli.cjs', '// stub\n');
  writeFixtureFile(root, '.pack-staging/bin/hooks.cjs', '// stub\n');
  writeFixtureFile(root, '.pack-staging/bin/mcp.cjs', '// stub\n');
  writeFixtureFile(root, '.pack-staging/install.mjs', 'export {};\n');
  writeFixtureFile(root, 'templates/adr.md', '# ADR\n');
  writeFixtureFile(
    root,
    'skills/phase-proposal/SKILL.md',
    '# proposal\n\n__SKILL:phase-proposal__\n',
  );
  writeFixtureFile(
    root,
    'agents/implementation-generator.md',
    '# gen\n\n__INCLUDE:static-analysis-gate__\n',
  );
  writeFixtureFile(root, '_fragments/static-analysis-gate.md', '');
  writeFixtureFile(root, '_fragments/static-analysis-gate.cursor.md', 'run_static_analysis gate\n');
}

/** 在源码树中写入已退役的 openspec 静态 bin 文件，模拟它们仍留在仓库里。 */
const RETIRED_PATHS = ['bin/openspec', 'bin/openspec-bundled.js', 'bin/openspec.cmd'];

function seedRetiredStaticBins(root: string): void {
  for (const rel of RETIRED_PATHS) {
    writeFixtureFile(root, rel, '// retired stub\n');
  }
}

/** 生成完整源码树并切换 cwd，返回临时根目录供用例继续改造。 */
function makeSourceRoot(prefix: string): string {
  const root = makeTempRoot(prefix);
  seedSourceTree(root);
  mockCwd(root);
  return root;
}

async function runAssembleAll(prefix = 'assemble-src-'): Promise<void> {
  makeSourceRoot(prefix);
  await assembleAll();
}

beforeEach(() => {
  outBase = makeTempRoot('assemble-out-');
  // 默认 cwd 指向空临时目录：用例忘写源码树时会直接失败，而不是回读仓库。
  mockCwd(makeTempRoot('assemble-no-source-'));
});

afterEach(() => {
  cwdSpy?.mockRestore();
  cwdSpy = undefined;
  vi.clearAllMocks();
  while (tempRoots.length > 0) {
    const dir = tempRoots.pop();
    if (dir) rmSync(dir, { recursive: true, force: true });
  }
});

describe('assembleAll', () => {
  const ASSEMBLE_TIMEOUT = 30_000;

  it(
    '三平台 outDir 均生成且无残留 __INCLUDE:',
    async () => {
      await runAssembleAll();
      for (const key of envMod.PRODUCT_ENV_KEYS) {
        const outDir = makeOutDir(key);
        const env = envMod.getEnv(key);
        const prefix = key === 'cursorHome' ? 'dev-team_' : '';
        const paths = [
          `agents/${prefix}implementation-generator.md`,
          `skills/${prefix}phase-proposal/SKILL.md`,
          env.hooksFilePath,
        ];
        expect(existsSync(outDir)).toBe(true);
        for (const rel of paths) {
          const full = join(outDir, rel);
          expect(existsSync(full)).toBe(true);
          const content = readFileSync(full, 'utf-8');
          expect(content).not.toContain('__INCLUDE:');
        }
      }
    },
    ASSEMBLE_TIMEOUT,
  );

  it(
    'Cursor/cursorHome outDir 的 hooks JSON 无 subagentStop 键',
    async () => {
      await runAssembleAll();
      for (const key of ['cursor', 'cursorHome'] as const) {
        const hooksPath = join(makeOutDir(key), envMod.getEnv(key).hooksFilePath);
        const parsed = JSON.parse(readFileSync(hooksPath, 'utf-8')) as {
          hooks: Record<string, unknown>;
        };
        expect(Object.hasOwn(parsed.hooks, 'subagentStop')).toBe(false);
      }
    },
    ASSEMBLE_TIMEOUT,
  );

  it(
    'Claude outDir hooks 含 SubagentStop 且 command 含 static-check',
    async () => {
      await runAssembleAll();
      const hooksPath = join(makeOutDir('claude'), envMod.getEnv('claude').hooksFilePath);
      const parsed = JSON.parse(readFileSync(hooksPath, 'utf-8')) as {
        hooks: { SubagentStop: Array<{ hooks: Array<{ command: string }> }> };
      };
      expect(parsed.hooks.SubagentStop.length).toBeGreaterThan(0);
      expect(parsed.hooks.SubagentStop[0]?.hooks[0]?.command).toContain('static-check');
    },
    ASSEMBLE_TIMEOUT,
  );

  it(
    'generator 引用缺失 fragment 时 assemble 失败',
    async () => {
      const root = makeSourceRoot('assemble-fixture-');
      writeFixtureFile(root, 'agents/broken-agent.md', '__INCLUDE:missing-fragment__\n');
      await expect(assembleAll()).rejects.toThrow();
    },
    ASSEMBLE_TIMEOUT,
  );

  it(
    'fragment 环引用时 assemble 失败',
    async () => {
      const root = makeSourceRoot('assemble-cycle-');
      writeFixtureFile(root, '_fragments/loop-a.md', '__INCLUDE:loop-b__');
      writeFixtureFile(root, '_fragments/loop-b.md', '__INCLUDE:loop-a__');
      writeFixtureFile(root, 'agents/cycle-agent.md', '__INCLUDE:loop-a__\n');
      await expect(assembleAll()).rejects.toThrow(/Include cycle|Include depth/);
    },
    ASSEMBLE_TIMEOUT,
  );

  it(
    '_fragments/ 存在于源码树但不出现在任一 env.outDir',
    async () => {
      const root = makeSourceRoot('assemble-fragments-');
      expect(existsSync(join(root, '_fragments'))).toBe(true);
      await assembleAll();
      for (const key of envMod.PRODUCT_ENV_KEYS) {
        expect(existsSync(join(makeOutDir(key), '_fragments'))).toBe(false);
      }
    },
    ASSEMBLE_TIMEOUT,
  );

  it(
    'Claude generator 无 run_static_analysis；Cursor 产物含该步骤',
    async () => {
      await runAssembleAll();
      const claudeAgent = readFileSync(
        join(makeOutDir('claude'), 'agents/implementation-generator.md'),
        'utf-8',
      );
      expect(claudeAgent).not.toContain('run_static_analysis');

      for (const key of ['cursor', 'cursorHome'] as const) {
        const prefix = key === 'cursorHome' ? 'dev-team_' : '';
        const agent = readFileSync(
          join(makeOutDir(key), `agents/${prefix}implementation-generator.md`),
          'utf-8',
        );
        expect(agent).toContain('run_static_analysis');
      }
    },
    ASSEMBLE_TIMEOUT,
  );

  it(
    'assemble 复制 templates 静态资源到各 outDir',
    async () => {
      await runAssembleAll();
      for (const key of envMod.PRODUCT_ENV_KEYS) {
        const outDir = makeOutDir(key);
        expect(existsSync(join(outDir, 'templates'))).toBe(true);
        expect(existsSync(join(outDir, 'templates/adr.md'))).toBe(true);
      }
    },
    ASSEMBLE_TIMEOUT,
  );

  it(
    'PRODUCT_ENV_KEYS 单轮全量执行失败即抛错',
    async () => {
      const root = makeSourceRoot('assemble-fail-fast-');
      rmSync(join(root, '_fragments/static-analysis-gate.md'));
      rmSync(join(root, '_fragments/static-analysis-gate.cursor.md'));
      await expect(assembleAll()).rejects.toThrow();
    },
    ASSEMBLE_TIMEOUT,
  );

  it(
    'STATIC_BIN_FILES 不再包含退役的 openspec 静态 bin 文件',
    async () => {
      const root = makeSourceRoot('assemble-static-bins-');
      seedRetiredStaticBins(root);
      await assembleAll();
      for (const key of envMod.PRODUCT_ENV_KEYS) {
        for (const rel of RETIRED_PATHS) {
          expect(existsSync(join(makeOutDir(key), rel))).toBe(false);
        }
      }
    },
    ASSEMBLE_TIMEOUT,
  );

  it(
    '空 .pack-staging/bin 目录时 assembleAll 仍完成且各 outDir 生成',
    async () => {
      const root = makeSourceRoot('assemble-empty-staging-');
      rmSync(join(root, '.pack-staging/bin'), { recursive: true, force: true });
      mkdirSync(join(root, '.pack-staging/bin'), { recursive: true });
      await expect(assembleAll()).resolves.toBeUndefined();
      for (const key of envMod.PRODUCT_ENV_KEYS) {
        expect(existsSync(makeOutDir(key))).toBe(true);
      }
    },
    ASSEMBLE_TIMEOUT,
  );

  it(
    '缺少 .pack-staging/bin 目录时 assembleAll 拒绝而非静默部分执行',
    async () => {
      const root = makeSourceRoot('assemble-no-staging-bin-');
      rmSync(join(root, '.pack-staging/bin'), { recursive: true, force: true });
      await expect(assembleAll()).rejects.toThrow();
    },
    ASSEMBLE_TIMEOUT,
  );

  it(
    '缺少 hooks/hooks.canonical.json 时 assembleAll 拒绝而非静默部分执行',
    async () => {
      const root = makeSourceRoot('assemble-no-hooks-');
      rmSync(join(root, 'hooks/hooks.canonical.json'));
      await expect(assembleAll()).rejects.toThrow();
    },
    ASSEMBLE_TIMEOUT,
  );

  it(
    'process.cwd 指向不存在路径时 assembleAll 抛出 ENOENT',
    async () => {
      const missing = join(tmpdir(), `assemble-missing-cwd-${Date.now()}`);
      mockCwd(missing);
      await expect(assembleAll()).rejects.toThrow();
    },
    ASSEMBLE_TIMEOUT,
  );

  it(
    '无 skills/ 与 agents/ 目录时 assembleAll 仍完成',
    async () => {
      const root = makeSourceRoot('assemble-no-skills-agents-');
      rmSync(join(root, 'skills'), { recursive: true, force: true });
      rmSync(join(root, 'agents'), { recursive: true, force: true });
      await expect(assembleAll()).resolves.toBeUndefined();
      for (const key of envMod.PRODUCT_ENV_KEYS) {
        const outDir = makeOutDir(key);
        expect(existsSync(outDir)).toBe(true);
        expect(existsSync(join(outDir, 'skills'))).toBe(false);
        expect(existsSync(join(outDir, 'agents'))).toBe(false);
      }
    },
    ASSEMBLE_TIMEOUT,
  );
});

bin/__tests__/archi-check-inventory/arch.source:
/**
 * 集成测试: change 文件清单 → archi_check 被查文件集（清单直通）
 *
 * 真实链路（模型解析与清单读取全为真实实现，不 mock）:
 * - `bin/src/lib/c4-cross-ref.ts` — 检查方（被查文件集组装与交叉引用）
 * - `bin/src/lib/file-inventory.ts` — 清单来源（真实 workflow.json 读盘）
 * - `bin/src/lib/c4-parser.ts` — 模型参照系（真实 openspec/architecture/models/*.c4 解析管线）
 * - `bin/src/commands/change-create.ts` — change fixture 的真实创建通道
 *
 * 只 mock 边界: node:child_process 与 child_process 的 execSync / execFileSync
 * （委托真实实现，仅作 staged 废弃用例的 not-called 断言）。project_root 经
 * runCrossRefCheck 首参显式传入临时工程根（与 inventory-backtrack-clear 同策略，
 * 不经 getProjectDir 解析链，亦不使用 process.chdir）。
 *
 * 覆盖 test-design「集成测试」场景: 清单直通检查。关联 AC: AC-9。
 *
 * @see openspec/changes/workflow-file-inventory/test-design.md — 集成测试「change 清单 → archi_check 被查文件集」
 */

import type * as LegacyChildProcess from 'child_process';
import * as fs from 'fs';
import type * as NodeChildProcess from 'node:child_process';
import * as os from 'os';
import * as path from 'path';

import { afterEach, beforeEach, describe, expect, it, vi } from 'vite-plus/test';

import { runChangeCreate } from '../../src/commands/change-create';
import { runCrossRefCheck } from '../../src/lib/c4-cross-ref';
import { writeFileInventory } from '../../src/lib/file-inventory';

// ---------------------------------------------------------------------------
// git 退场 / staged 废弃防回归：child_process 全程 spy（仅作 not-called 断言）
// ---------------------------------------------------------------------------

vi.mock('node:child_process', async () => {
  const actual = await vi.importActual<typeof NodeChildProcess>('node:child_process');
  return { ...actual, execSync: vi.fn(actual.execSync), execFileSync: vi.fn(actual.execFileSync) };
});

vi.mock('child_process', async () => {
  const actual = await vi.importActual<typeof LegacyChildProcess>('child_process');
  return { ...actual, execSync: vi.fn(actual.execSync), execFileSync: vi.fn(actual.execFileSync) };
});

import { execSync as spiedExecSync } from 'node:child_process';

// ---------------------------------------------------------------------------
// Fixture：真实 .c4 模型 + 真实源文件 + runChangeCreate 创建的真实 change
// ---------------------------------------------------------------------------

const CHANGE = 'inv-change';

/** 两元素以上、声明 Frontend -> Backend 一条关系的模型（走真实 LikeC4 解析管线）。 */
const MODEL_DSL = `specification {
  element package
}
model {
  package Frontend {
    metadata { path './src/frontend/' }
  }
  package Backend {
    metadata { path './src/backend/' }
  }
  package Auth {
    metadata { path './src/auth/' }
  }
  Frontend -> Backend "calls API"
}`;

const SOURCE_FILES: Record<string, string> = {
  // 已建模文件：import Backend（关系已声明，合法）+ import Auth（关系未声明 → violation）
  'src/frontend/app.ts':
    "import { api } from '../backend/api';\nimport { guard } from '../auth/guard';",
  'src/backend/api.ts': 'export const api = () => {};',
  'src/auth/guard.ts': 'export const guard = () => {};',
  // 未建模文件（测试文件——清单直通不做 test config 过滤的可见证据）
  'src/unmapped/app.test.ts': 'export const smoke = 1;',
};

let projectRoot: string;

function writeModelFixture(): void {
  const modelsDir = path.join(projectRoot, 'openspec', 'architecture', 'models');
  fs.mkdirSync(modelsDir, { recursive: true });
  fs.writeFileSync(path.join(modelsDir, 'spec.c4'), MODEL_DSL, 'utf-8');
}

function writeSourceFiles(): void {
  for (const [rel, content] of Object.entries(SOURCE_FILES)) {
    const full = path.join(projectRoot, rel);
    fs.mkdirSync(path.dirname(full), { recursive: true });
    fs.writeFileSync(full, content, 'utf-8');
  }
}

/** runChangeCreate 真实创建 change，inventory 缺省即初始空净状态。 */
function createChange(inventory?: { written: string[]; deleted: string[] }): string {
  const created = runChangeCreate(CHANGE, projectRoot, 'requirement');
  if (inventory) {
    writeFileInventory(created.path, inventory);
  }
  return created.path;
}

/** 机制前旧 change：手工写入无 files 字段的 workflow.json。 */
function createLegacyChange(): string {
  const changeDir = path.join(projectRoot, 'openspec', 'changes', CHANGE);
  fs.mkdirSync(changeDir, { recursive: true });
  fs.writeFileSync(
    path.join(changeDir, 'workflow.json'),
    JSON.stringify({ workflow_type: 'requirement', created: '2026-09-17' }),
    'utf-8',
  );
  return changeDir;
}

beforeEach(() => {
  projectRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'archi-check-inv-'));
  writeModelFixture();
  writeSourceFiles();
});

afterEach(() => {
  fs.rmSync(projectRoot, { recursive: true, force: true });
});

// ===========================================================================
// 场景: 清单直通检查
// ===========================================================================

describe('场景: 清单直通检查（change 清单 → archi_check 被查文件集）', () => {
  it('正向：change 清单模式 → files.written 全量参与被查（测试文件直通不过滤），matched / unmatched_files / violations 反映直通集合 (AC-9)', async () => {
    createChange({ written: ['src/frontend/app.ts', 'src/unmapped/app.test.ts'], deleted: [] });

    const result = await runCrossRefCheck(projectRoot, { change: CHANGE });

    // 直通集合整体进入被查：已建模文件按模型映射匹配 Frontend
    expect(result.matched).toEqual([{ element_id: 'Frontend', files: ['src/frontend/app.ts'] }]);
    // 测试文件未被过滤，原样进 unmatched_files（直通的可见后果）
    expect(result.unmatched_files).toEqual(['src/unmapped/app.test.ts']);
    // app.ts import Backend（关系已声明，合法）+ import Auth（关系未声明）→ 恰一条 unmodeled_dependency
    expect(result.violations).toHaveLength(1);
    expect(result.violations[0]).toMatchObject({
      type: 'unmodeled_dependency',
      source: 'Frontend',
      target: 'Auth',
      file: 'src/frontend/app.ts',
    });
    expect(result.warnings).toEqual([]);
    expect(result.status).toBe('violations_found');
  });

  it('正向：显式 files 与 change 同传 → files 优先，清单不参与被查 (AC-9)', async () => {
    // 清单 written 本会匹配 Frontend；显式 files 胜出后被查集合只有显式列表
    createChange({ written: ['src/frontend/app.ts'], deleted: [] });

    const result = await runCrossRefCheck(projectRoot, {
      change: CHANGE,
      files: ['src/unmapped/app.test.ts'],
    });

    expect(result.matched).toEqual([]);
    expect(result.unmatched_files).toEqual(['src/unmapped/app.test.ts']);
    expect(result.status).toBe('clean');
  });

  it('边界：written 为空数组 → status no_changes（不报错、不产出违规）', async () => {
    createChange(); // runChangeCreate 初始 files = { written: [], deleted: [] }

    const result = await runCrossRefCheck(projectRoot, { change: CHANGE });

    expect(result.status).toBe('no_changes');
    expect(result.violations).toEqual([]);
    expect(result.matched).toEqual([]);
    expect(result.unmatched_files).toEqual([]);
  });

  it('异常：staged: true → 显式抛错（清单模式替代），且全程无任何 git 子进程调用 (AC-9)', async () => {
    createChange({ written: ['src/frontend/app.ts'], deleted: [] });

    await expect(runCrossRefCheck(projectRoot, { staged: true })).rejects.toThrow(
      /staged 模式已由清单模式替代/,
    );
    expect(vi.mocked(spiedExecSync)).not.toHaveBeenCalled();
  });

  it('异常：无 files 的机制前旧 change → 硬报错指引重建（模型在场，非静默 skipped，AC-9）', async () => {
    createLegacyChange();

    await expect(runCrossRefCheck(projectRoot, { change: CHANGE })).rejects.toThrow(
      /该 change 创建于文件清单机制之前，请重建/,
    );
  });
});

