        expect(stderrText).toContain('Unknown subcommand:');
        expect(stderrText).toContain(sub);
      } finally {
        process.argv = original;
      }
    }
    stderrSpy.mockRestore();
  });

  it('恰好 protect-files / static-check 字面量调度；多余 argv 后缀不改变子命令选择', () => {
