/**
 * 集成测试: non-zero-exit-code
 *
 * 覆盖范围:
 * - AC-11: 测试命令非零退出时记录失败和退出码
 * - AC-11: 非零退出不阻塞同项目其他 framework 执行
 * - AC-11: 所有 framework 执行完成后退出码反映汇总结果
 *
 * @see openspec/changes/cli-unit-test-execute/test-design.md
 */

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';

import { beforeEach, describe, it, expect, vi } from 'vite-plus/test';

import { runTestExecution } from '../../src/commands/test-execution';
import type { ExecutionResult } from '../../src/lib/test-runner';
import type { SourceFileEntry, TestExecutionSubReport, TestPlan } from '../../src/schemas';

function sf(file: string): SourceFileEntry {
  return {
    file,
    coverage: {
      lines: 0,
      branches: null,
      functions: null,
      total_lines: null,
      covered_lines: null,
      total_branches: null,
      covered_branches: null,
      total_functions: null,
      covered_functions: null,
    },
  };
}

// ---------------------------------------------------------------------------
// Mocks
// ---------------------------------------------------------------------------

const mockDetectFrameworks = vi.fn();
const mockExecutePlanEntry = vi.fn();
const mockGenerateSubReport = vi.fn();
const mockGenerateSummaryReport = vi.fn();

vi.mock('../../src/commands/test-detect-frameworks', () => ({
  runTestDetectFrameworks: (...args: unknown[]) => mockDetectFrameworks(...args),
}));

vi.mock('../../src/lib/test-runner', () => ({
  executePlanEntry: (...args: unknown[]) => mockExecutePlanEntry(...args),
}));

vi.mock('../../src/lib/test-report', () => ({
  generateSubReport: (...args: unknown[]) => mockGenerateSubReport(...args),
  generateSummaryReport: (...args: unknown[]) => mockGenerateSummaryReport(...args),
}));

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

interface TempProject {
  root: string;
  cleanup: () => void;
}

function createTempProject(): TempProject {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'non-zero-exit-'));
  const openspecDir = path.join(root, 'openspec');
  fs.mkdirSync(openspecDir, { recursive: true });
  fs.writeFileSync(
    path.join(openspecDir, 'config.json'),
    JSON.stringify({ schema: 'spec-driven', test: { framework: 'vitest' } }, null, 2),
    'utf-8',
  );
  return { root, cleanup: () => fs.rmSync(root, { recursive: true, force: true }) };
}

function makePlanEntry(overrides: Partial<TestPlan> = {}): TestPlan {
  return {
    cwd: '.',
    root: '.',
    framework: 'vitest',
    coverage_format: 'istanbul',
    coverage_output: 'coverage-summary.json',
    mutation_cwd: '.',
    mutation_script: null,
    script: {
      shell: '#!/bin/bash\nset -e\n\nnpx vitest run --coverage --coverage.reporter=json-summary',
      cmd: 'npx vitest run --coverage --coverage.reporter=json-summary',
    },
    ...overrides,
  };
}

function makeExecutionResult(overrides: Partial<ExecutionResult> = {}): ExecutionResult {
  return {
    framework: 'vitest',
    exitCode: 0,
    testCases: [{ name: 'test1', status: 'passed', durationMs: 100 }],
    coverage: null,
    mutation: null,
    durationMs: 500,
    testFiles: ['src/foo.test.ts'],
    sourceFiles: ['src/foo.ts'],
    planId: 'vitest',
    reportDir: '/tmp/reports/test/vitest',
    ...overrides,
  };
}

function makeSubReport(
  framework = 'vitest',
  overrides: Record<string, unknown> = {},
): TestExecutionSubReport {
  return {
    framework,
    root: '.',
    timestamp: '2026-07-01T00:00:00.000Z',
    exit_code: 0,
    duration_ms: 500,
    summary: { total: 1, passed: 1, failed: 0, skipped: 0 },
    error_cases: [],
    test_files: ['src/foo.test.ts'],
    source_files: [sf('src/foo.ts')],
    coverage: null,
    mutation: null,
    ...overrides,
  };
}

// ===========================================================================
// AC-11: 非零退出码
// ===========================================================================

describe('non-zero-exit-code (AC-11)', () => {
  beforeEach(() => {
    mockDetectFrameworks.mockReset();
    mockExecutePlanEntry.mockReset();
    mockGenerateSubReport.mockReset();
    mockGenerateSummaryReport.mockReset();
  });

  it('测试命令非零退出时记录失败和退出码', async () => {
    const project = createTempProject();
    try {
      mockDetectFrameworks.mockReturnValue({
        detected: [{ file: 'src/foo.test.ts', framework: 'vitest' }],
        plan: [makePlanEntry()],
      });
      mockExecutePlanEntry.mockReturnValue(
        makeExecutionResult({
          exitCode: 1,
          testCases: [
            {
              name: 'failing_test',
              status: 'failed',
              durationMs: 50,
              errorMessage: 'AssertionError',
            },
          ],
        }),
      );
      mockGenerateSubReport.mockReturnValue(
        makeSubReport('vitest', {
          exit_code: 1,
          summary: { total: 1, passed: 0, failed: 1, skipped: 0 },
        }),
      );
      mockGenerateSummaryReport.mockReturnValue({
        phase: 'test-execution',
        command: 'dev-team test-execution',
        timestamp: '2026-07-01T00:00:00.000Z',
        duration_seconds: 1,
        total: 1,
        passed: 0,
        failed: 1,
        skipped: 0,
        conclusion: 'fail',
        problems: [{ framework: 'vitest', type: 'test_failure', message: 'Test failed' }],
        coverage: null,
      });

      const exitCode = await runTestExecution({ projectRoot: project.root });

      expect(exitCode).toBe(1);
      expect(mockExecutePlanEntry).toHaveBeenCalledTimes(1);
    } finally {
      project.cleanup();
    }
  });

  it('非零退出不阻塞同项目其他 framework 执行', async () => {
    const project = createTempProject();
    try {
      mockDetectFrameworks.mockReturnValue({
        detected: [
          { file: 'src/foo.test.ts', framework: 'vitest' },
          { file: 'tests/bar.test.ts', framework: 'vite-plus' },
        ],
        plan: [makePlanEntry({ framework: 'vitest' }), makePlanEntry({ framework: 'vite-plus' })],
      });
      // vitest 失败
      mockExecutePlanEntry.mockReturnValueOnce(
        makeExecutionResult({
          framework: 'vitest',
          exitCode: 1,
          testCases: [{ name: 'fail', status: 'failed', errorMessage: 'Error' }],
        }),
      );
      // vite-plus 成功
      mockExecutePlanEntry.mockReturnValueOnce(
        makeExecutionResult({
          framework: 'vite-plus',
          testCases: [{ name: 'pass', status: 'passed' }],
        }),
      );
      mockGenerateSubReport
        .mockReturnValueOnce(
          makeSubReport('vitest', {
            exit_code: 1,
            summary: { total: 1, passed: 0, failed: 1, skipped: 0 },
          }),
        )
        .mockReturnValueOnce(makeSubReport('vite-plus'));
      mockGenerateSummaryReport.mockReturnValue({
        phase: 'test-execution',
        command: 'dev-team test-execution',
        timestamp: '2026-07-01T00:00:00.000Z',
        duration_seconds: 1,
        total: 2,
        passed: 1,
        failed: 1,
        skipped: 0,
        conclusion: 'fail',
        problems: [{ framework: 'vitest', type: 'test_failure', message: 'Error' }],
        coverage: null,
      });

      const exitCode = await runTestExecution({ projectRoot: project.root });

      // 两个框架都应被执行
      expect(mockExecutePlanEntry).toHaveBeenCalledTimes(2);
      expect(mockGenerateSubReport).toHaveBeenCalledTimes(2);
      // 最终退出码为 1
      expect(exitCode).toBe(1);
    } finally {
      project.cleanup();
    }
  });

  it('所有 framework 执行完成后退出码反映汇总结果', async () => {
    const project = createTempProject();
    try {
      mockDetectFrameworks.mockReturnValue({
        detected: [{ file: 'src/foo.test.ts', framework: 'vitest' }],
        plan: [makePlanEntry()],
      });
      mockExecutePlanEntry.mockReturnValue(
        makeExecutionResult({
          testCases: [{ name: 't1', status: 'passed' }],
        }),
      );
      mockGenerateSubReport.mockReturnValue(makeSubReport());
      mockGenerateSummaryReport.mockReturnValue({
        phase: 'test-execution',
        command: 'dev-team test-execution',
        timestamp: '2026-07-01T00:00:00.000Z',
        duration_seconds: 1,
        total: 1,
        passed: 1,
        failed: 0,
        skipped: 0,
        conclusion: 'pass',
        problems: [],
        coverage: null,
      });

      const exitCode = await runTestExecution({ projectRoot: project.root });

      // 所有测试通过，退出码为 0
      expect(exitCode).toBe(0);
      expect(mockGenerateSummaryReport).toHaveBeenCalledTimes(1);
    } finally {
      project.cleanup();
    }
  });
});

bin/src/commands/backtrack.test.ts.source:
/**
 * 单元测试: backtrack.ts — backtrack MCP 工具核心实现。
 *
 * 测试覆盖:
 * - 正常回溯操作（AC-2、AC-3）
 * - 目标合法性验证
 * - 严格前置条件（缺文件 / 格式非法即终止）
 * - 幂等性
 *
 * 评估历史存放在 `workflow.json.eval`；本命令只经 `writeEvalJson` 持久化，
 * 从不直接写 `eval.json`。
 */

import * as fs from 'fs';

import { describe, it, expect, vi, beforeEach } from 'vite-plus/test';

vi.mock('fs', async (importOriginal) => {
  const actual = await importOriginal<typeof fs>();
  return {
    ...actual,
    existsSync: vi.fn(),
    readFileSync: vi.fn(),
    writeFileSync: vi.fn(),
    mkdirSync: vi.fn(),
    unlinkSync: vi.fn(),
  };
});

vi.mock('../lib/eval-json', async () => {
  const actual = await vi.importActual('../lib/eval-json');
  return {
    ...actual,
    readEvalJson: vi.fn(),
    writeEvalJson: vi.fn(),
  };
});

vi.mock('../lib/file-inventory', async () => {
  const actual = await vi.importActual('../lib/file-inventory');
  return {
    ...actual,
    readFileInventory: vi.fn(),
    writeFileInventory: vi.fn(),
  };
});

vi.mock('../lib/change', () => ({
  getChangeDir: vi.fn(() => '/tmp/test-change'),
}));

vi.mock('../lib/change-config', () => ({
  getWorkflowType: vi.fn(() => 'requirement'),
}));

import { getWorkflowType } from '../lib/change-config';
import { readEvalJson, writeEvalJson, type EvalEntry } from '../lib/eval-json';
import { readFileInventory, writeFileInventory } from '../lib/file-inventory';
import { backtrackInputSchema } from '../schemas';
import { runBacktrack } from './backtrack';

const FIXTURE_PROJECT_ROOT = '/tmp/fixture-project';

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function makePassEntry(
  phase: EvalEntry['phase'],
  attempt: number = 1,
  overrides: Partial<EvalEntry> = {},
): EvalEntry {
  return {
    phase,
    verdict: 'pass',
    attempt,
    timestamp: new Date(Date.now() + attempt).toISOString(),
    backtrack_to: null,
    report: '',
    checklist: [],
    ...overrides,
  };
}

function makeFailEntry(
  phase: EvalEntry['phase'],
  attempt: number = 1,
  overrides: Partial<EvalEntry> = {},
): EvalEntry {
  return {
    phase,
    verdict: 'fail',
    attempt,
    timestamp: new Date(Date.now() + attempt).toISOString(),
    backtrack_to: null,
    report: '',
    checklist: [],
    ...overrides,
  };
}

const defaultEntries: EvalEntry[] = [
  makePassEntry('proposal', 1),
  makePassEntry('dev-design', 1),
  makePassEntry('test-design', 1),
  makePassEntry('test-gen', 1),
  makePassEntry('implement', 1),
  makeFailEntry('test-execution', 1),
];

/** 断言本命令没有直接写 / 删磁盘上的 `eval.json`（迁移由 writeEvalJson 负责）。 */
function expectNoLegacyWrite(): void {
  for (const call of vi.mocked(fs.writeFileSync).mock.calls) {
    expect(String(call[0]).endsWith('eval.json')).toBe(false);
  }
  expect(vi.mocked(fs.unlinkSync)).not.toHaveBeenCalled();
}

beforeEach(() => {
  vi.clearAllMocks();
  vi.mocked(readEvalJson).mockReset().mockReturnValue(defaultEntries);
  vi.mocked(writeEvalJson).mockReset();
  vi.mocked(getWorkflowType).mockReset().mockReturnValue('requirement');
  // files 清单默认合法（非清空规则用例不触碰它）
  vi.mocked(readFileInventory).mockReset().mockReturnValue({ written: [], deleted: [] });
  vi.mocked(writeFileInventory).mockReset();
});

// ---------------------------------------------------------------------------
// 正常回溯操作
// ---------------------------------------------------------------------------

describe('runBacktrack — 正常回溯操作', () => {
  it('runBacktrack 修改指定 phase 最新 entry 的 backtrack_to 为 "test-gen"，backtrack_reason 为指定原因', () => {
    const result = runBacktrack({
      project_root: FIXTURE_PROJECT_ROOT,
      change: 'test-change',
      phase: 'test-execution',
      backtrack_to: 'test-gen',
      backtrack_reason: '语法错误',
    });

    expect(result.modified).toBe(true);
    expect(writeEvalJson).toHaveBeenCalledTimes(1);

    const writtenEntries = vi.mocked(writeEvalJson).mock.calls[0][1];
    const testExecEntry = writtenEntries.find((e) => e.phase === 'test-execution')!;
    expect(testExecEntry.backtrack_to).toBe('test-gen');
    expect(testExecEntry.backtrack_reason).toBe('语法错误');
  });

  it('调用 writeEvalJson 一次且数组长度不变；不出现对 eval.json 的直接写入（AC-4）', () => {
    runBacktrack({
      project_root: FIXTURE_PROJECT_ROOT,
      change: 'test-change',
      phase: 'test-execution',
      backtrack_to: 'test-gen',
      backtrack_reason: '语法错误',
    });

    expect(writeEvalJson).toHaveBeenCalledTimes(1);
    expect(vi.mocked(writeEvalJson).mock.calls[0][1]).toHaveLength(defaultEntries.length);
    expectNoLegacyWrite();
  });

  it('返回 { modified: true, phase, target }', () => {
    const result = runBacktrack({
      project_root: FIXTURE_PROJECT_ROOT,
      change: 'test-change',
      phase: 'test-execution',
      backtrack_to: 'test-gen',
      backtrack_reason: '语法错误',
    });

    expect(result).toEqual({
      modified: true,
      phase: 'test-execution',
      target: 'test-gen',
    });
  });

  it('标记目标 phase test-gen 的最新 pass entry 为 stale: true', () => {
    runBacktrack({
      project_root: FIXTURE_PROJECT_ROOT,
      change: 'test-change',
      phase: 'test-execution',
      backtrack_to: 'test-gen',
      backtrack_reason: '语法错误',
    });

    const writtenEntries = vi.mocked(writeEvalJson).mock.calls[0][1];
    const testGenEntry = writtenEntries.find((e) => e.phase === 'test-gen')!;
    expect(testGenEntry.stale).toBe(true);
  });

  it('stale 标记向下游传播到 test-execution 等依赖 phase', () => {
    const entries: EvalEntry[] = [
      makePassEntry('proposal', 1),
      makePassEntry('dev-design', 1),
      makePassEntry('test-design', 1),
      makePassEntry('test-gen', 1),
      makePassEntry('implement', 1),
      makePassEntry('test-execution', 1),
      makePassEntry('code-review', 1),
      makePassEntry('acceptance', 1),
    ];
    vi.mocked(readEvalJson).mockReturnValue(entries);

    runBacktrack({
      project_root: FIXTURE_PROJECT_ROOT,
      change: 'test-change',
      phase: 'test-execution',
      backtrack_to: 'test-gen',
      backtrack_reason: '语法错误',
    });

    const writtenEntries = vi.mocked(writeEvalJson).mock.calls[0][1];

    // test-gen 被标记 stale
    expect(writtenEntries.find((e) => e.phase === 'test-gen')!.stale).toBe(true);
    // test-gen 的 downstream: test-execution, code-review 也应被标记 stale
    expect(writtenEntries.find((e) => e.phase === 'test-execution')!.stale).toBe(true);
    expect(writtenEntries.find((e) => e.phase === 'code-review')!.stale).toBe(true);
    // 非 downstream 不应被标记
    expect(writtenEntries.find((e) => e.phase === 'proposal')!.stale).toBeUndefined();
    expect(writtenEntries.find((e) => e.phase === 'dev-design')!.stale).toBeUndefined();
    expect(writtenEntries.find((e) => e.phase === 'implement')!.stale).toBeUndefined();
  });

  it('多 workflow 类型（requirement、test-only）均正常工作', () => {
    // requirement 已由默认 mock 覆盖，测试 test-only
    vi.mocked(getWorkflowType).mockReturnValue('test-only');

    const entries: EvalEntry[] = [
      makePassEntry('proposal', 1),
      makePassEntry('code-analyze', 1),
      makePassEntry('test-design', 1),
      makePassEntry('test-gen', 1),
      makeFailEntry('test-execution', 1),
    ];
    vi.mocked(readEvalJson).mockReturnValue(entries);

    const result = runBacktrack({
      project_root: FIXTURE_PROJECT_ROOT,
      change: 'test-change',
      phase: 'test-execution',
      backtrack_to: 'test-gen',
      backtrack_reason: '测试失败需回溯',
    });

    expect(result.modified).toBe(true);
    expect(result.target).toBe('test-gen');

    const writtenEntries = vi.mocked(writeEvalJson).mock.calls[0][1];
    expect(writtenEntries.find((e) => e.phase === 'test-execution')!.backtrack_to).toBe('test-gen');
    expect(writtenEntries.find((e) => e.phase === 'test-gen')!.stale).toBe(true);
  });
});

// ---------------------------------------------------------------------------
// 目标合法性验证
// ---------------------------------------------------------------------------

describe('runBacktrack — 目标合法性验证', () => {
  it('backtrack_to 等于当前 phase 时允许回溯（重新执行当前 phase）', () => {
    const entries: EvalEntry[] = [
      makePassEntry('proposal', 1),
      makePassEntry('dev-design', 1),
      makePassEntry('test-design', 1),
      makePassEntry('test-gen', 1),
      makePassEntry('implement', 1),
      makeFailEntry('test-execution', 1),
    ];
    vi.mocked(readEvalJson).mockReturnValue(entries);

    const result = runBacktrack({
      project_root: FIXTURE_PROJECT_ROOT,
      change: 'test-change',
      phase: 'test-execution',
      backtrack_to: 'test-execution',
      backtrack_reason: '重新执行当前 phase',
    });

    expect(result.modified).toBe(true);
    expect(result.target).toBe('test-execution');

    const writtenEntries = vi.mocked(writeEvalJson).mock.calls[0][1];
    const testExecEntry = writtenEntries.find((e) => e.phase === 'test-execution')!;
    expect(testExecEntry.backtrack_to).toBe('test-execution');
    expect(testExecEntry.backtrack_reason).toBe('重新执行当前 phase');
  });

  it('backtrack_to 在当前 phase 之后时抛出错误且不写盘（AC-3）', () => {
    expect(() =>
      runBacktrack({
        project_root: FIXTURE_PROJECT_ROOT,
        change: 'test-change',
        phase: 'test-gen',
        backtrack_to: 'acceptance',
        backtrack_reason: 'acceptance 在 test-gen 之后',
      }),
    ).toThrow(/无效的回溯目标 phase/);

    expect(writeEvalJson).not.toHaveBeenCalled();
  });

  it('backtrack_to 不在 phase 表中时抛出错误且不写盘', () => {
    expect(() =>
      runBacktrack({
        project_root: FIXTURE_PROJECT_ROOT,
        change: 'test-change',
        phase: 'test-execution',
        backtrack_to: 'nonexistent-phase',
        backtrack_reason: '不存在的 phase',
      }),
    ).toThrow(/不包含 phase/);

    expect(writeEvalJson).not.toHaveBeenCalled();
  });

  it('phase 不在 phase 表中时抛出错误且不写盘', () => {
    expect(() =>
      runBacktrack({
        project_root: FIXTURE_PROJECT_ROOT,
        change: 'test-change',
        phase: 'invalid-phase',
        backtrack_to: 'test-gen',
        backtrack_reason: '不存在的 phase',
      }),
    ).toThrow(/不包含 phase/);

    expect(writeEvalJson).not.toHaveBeenCalled();
  });

  it('该 phase 无任何评估条目时抛错，message 含「没有评估条目」且不含 eval.json（AC-4）', () => {
    vi.mocked(readEvalJson).mockReturnValue([makePassEntry('proposal', 1)]);

    let captured: Error | null = null;
    try {
      runBacktrack({
        project_root: FIXTURE_PROJECT_ROOT,
        change: 'test-change',
        phase: 'test-execution',
        backtrack_to: 'proposal',
        backtrack_reason: 'no entry',
      });
    } catch (e: unknown) {
      captured = e as Error;
    }

    expect(captured).not.toBeNull();
    expect(captured!.message).toContain('没有评估条目');
    expect(captured!.message).not.toContain('eval.json');
    expect(writeEvalJson).not.toHaveBeenCalled();
  });

  it('目标 phase 无任何 entry 时不报错（markPhaseStale 是 no-op）', () => {
    vi.mocked(readEvalJson).mockReturnValue([
      makePassEntry('proposal', 1),
      makePassEntry('dev-design', 1),
      makeFailEntry('test-execution', 1),
    ]);

    // test-gen 无任何 entry — markPhaseStale 视为 no-op，不应报错
    const result = runBacktrack({
      project_root: FIXTURE_PROJECT_ROOT,
      change: 'test-change',
      phase: 'test-execution',
      backtrack_to: 'test-gen',
      backtrack_reason: '目标无 entry',
    });

    expect(result.modified).toBe(true);

    const writtenEntries = vi.mocked(writeEvalJson).mock.calls[0][1];
    const testExecEntry = writtenEntries.find((e) => e.phase === 'test-execution')!;
    expect(testExecEntry.backtrack_to).toBe('test-gen');
    expect(testExecEntry.backtrack_reason).toBe('目标无 entry');
  });

  it('目标 phase 有 entry 但无 pass entry 时 markPhaseStale 为 no-op，不抛错', () => {
    const entries: EvalEntry[] = [
      makePassEntry('proposal', 1),
      makePassEntry('dev-design', 1),
      makeFailEntry('test-gen', 1), // test-gen 只有 fail entry
      makeFailEntry('test-execution', 1),
    ];
    vi.mocked(readEvalJson).mockReturnValue(entries);

    const result = runBacktrack({
      project_root: FIXTURE_PROJECT_ROOT,
      change: 'test-change',
      phase: 'test-execution',
      backtrack_to: 'test-gen',
      backtrack_reason: '语法错误',
    });

    expect(result.modified).toBe(true);
    const writtenEntries = vi.mocked(writeEvalJson).mock.calls[0][1];
    const testGenEntry = writtenEntries.find((e) => e.phase === 'test-gen')!;
    // markPhaseStale 是 no-op，但不应抛错
    expect(testGenEntry.stale).toBeUndefined();
  });
});

// ---------------------------------------------------------------------------
// 严格前置条件与错误包装
// ---------------------------------------------------------------------------

describe('runBacktrack — 严格前置条件 (AC-13, AC-14)', () => {
  it('getWorkflowType 因 workflow.json 缺失抛错时原样透出，message 含 change_create 指引且不写盘（AC-13）', () => {
    vi.mocked(getWorkflowType).mockImplementation(() => {
      throw new Error(
        'workflow.json 不存在: /tmp/test-change/workflow.json。该文件由 change_create 建立，是工作流的前置条件；请通过 change_create 或 workflow-* skill 创建 change，不要手写该文件。',
      );
    });

    let captured: Error | null = null;
    try {
      runBacktrack({
        project_root: FIXTURE_PROJECT_ROOT,
        change: 'test-change',
        phase: 'test-execution',
        backtrack_to: 'test-gen',
        backtrack_reason: '语法错误',
      });
    } catch (e: unknown) {
      captured = e as Error;
    }

    expect(captured).not.toBeNull();
    expect(captured!.message).toContain('workflow.json 不存在');
    expect(captured!.message).toContain('change_create');
    expect(writeEvalJson).not.toHaveBeenCalled();
    expect(readEvalJson).not.toHaveBeenCalled();
  });

  it('getWorkflowType 因 JSON 非法 / 根非对象 / workflow_type 非枚举抛错时原样透出，不写盘（AC-14）', () => {
    for (const message of [
      'workflow.json 解析失败: Unexpected token',
      'workflow.json 根元素必须是对象，但实际类型为 object',
      'workflow.json 格式非法 (/tmp/test-change/workflow.json): workflow_type: Invalid input',
    ]) {
      vi.mocked(getWorkflowType).mockImplementation(() => {
        throw new Error(message);
      });

      expect(() =>
        runBacktrack({
          project_root: FIXTURE_PROJECT_ROOT,
          change: 'test-change',
          phase: 'test-execution',
          backtrack_to: 'test-gen',
          backtrack_reason: '语法错误',
        }),
      ).toThrow(message);
      expect(writeEvalJson).not.toHaveBeenCalled();
    }
  });

  it('readEvalJson 抛错时包装为「读取 workflow.json 失败:」+ 原因', () => {
    vi.mocked(readEvalJson).mockImplementation(() => {
      throw new Error('workflow.json.eval 必须是数组，但实际类型为 object');
    });

    expect(() =>
      runBacktrack({
        project_root: FIXTURE_PROJECT_ROOT,
        change: 'test-change',
        phase: 'test-execution',
        backtrack_to: 'test-gen',
        backtrack_reason: '语法错误',
      }),
    ).toThrow(/读取 workflow\.json 失败: workflow\.json\.eval 必须是数组/);

    expect(writeEvalJson).not.toHaveBeenCalled();
  });

  it('writeEvalJson 抛错时包装为「写入 workflow.json 失败:」+ 原因', () => {
    vi.mocked(writeEvalJson).mockImplementation(() => {
      throw new Error('workflow.json 格式非法 (/tmp/test-change/workflow.json): eval: 未知');
    });

    expect(() =>
      runBacktrack({
        project_root: FIXTURE_PROJECT_ROOT,
        change: 'test-change',
        phase: 'test-execution',
        backtrack_to: 'test-gen',
        backtrack_reason: '语法错误',
      }),
    ).toThrow(/写入 workflow\.json 失败: workflow\.json 格式非法/);
  });

  it('writeEvalJson 因文件缺失拒绝时抛错且不创建任何文件（AC-13）', () => {
    vi.mocked(writeEvalJson).mockImplementation(() => {
      throw new Error(
        'workflow.json 不存在: /tmp/test-change/workflow.json，无法写入评估记录。请先通过 change_create 创建 change。',
      );
    });

    let captured: Error | null = null;
    try {
      runBacktrack({
        project_root: FIXTURE_PROJECT_ROOT,
        change: 'test-change',
        phase: 'test-execution',
        backtrack_to: 'test-gen',
        backtrack_reason: '语法错误',
      });
    } catch (e: unknown) {
      captured = e as Error;
    }

    expect(captured).not.toBeNull();
    expect(captured!.message).toContain('写入 workflow.json 失败:');
    expect(captured!.message).toContain('change_create');
    expect(vi.mocked(fs.writeFileSync)).not.toHaveBeenCalled();
    expect(vi.mocked(fs.mkdirSync)).not.toHaveBeenCalled();
  });
});

