// ---------------------------------------------------------------------------

describe('runBacktrack — 幂等性', () => {
  it('连续调用两次 backtrack 结果一致（第二次覆盖第一次的设置）', () => {
    const opts = {
      project_root: FIXTURE_PROJECT_ROOT,
      change: 'test-change',
      phase: 'test-execution',
      backtrack_to: 'test-gen',
      backtrack_reason: '第一次回溯原因',
    };

    const firstResult = runBacktrack(opts);
    const firstWritten = vi.mocked(writeEvalJson).mock.calls[0][1];

    // 重置 mock 以捕获第二次写入
    vi.mocked(writeEvalJson).mockClear();

    // 第二次调用，使用不同的原因
    const secondResult = runBacktrack({
      ...opts,
      backtrack_reason: '第二次回溯原因（覆盖）',
    });

    expect(firstResult.modified).toBe(true);
    expect(secondResult.modified).toBe(true);

    const secondWritten = vi.mocked(writeEvalJson).mock.calls[0][1];
    const secondExecEntry = secondWritten.find((e) => e.phase === 'test-execution')!;

    // 第二次的 reason 覆盖了第一次
    expect(secondExecEntry.backtrack_reason).toBe('第二次回溯原因（覆盖）');
    // 两次写入的条目总数一致
    expect(firstWritten.length).toBe(secondWritten.length);
  });
});

// ---------------------------------------------------------------------------
// files 清空规则 (AC-6)
// ---------------------------------------------------------------------------

describe('runBacktrack — files 清空规则 (AC-6)', () => {
  it('backtrack 到 implement → writeFileInventory 以空净状态被调用 (AC-6)', () => {
    runBacktrack({
      project_root: FIXTURE_PROJECT_ROOT,
      change: 'test-change',
      phase: 'test-execution',
      backtrack_to: 'implement',
      backtrack_reason: '实现方案推翻',
    });

    expect(readFileInventory).toHaveBeenCalledWith('/tmp/test-change');
    expect(writeFileInventory).toHaveBeenCalledTimes(1);
    expect(writeFileInventory).toHaveBeenCalledWith('/tmp/test-change', {
      written: [],
      deleted: [],
    });
  });

  it('backtrack 到 implement 之前的 phase（如 proposal / dev-design）→ 同样清空 (AC-6)', () => {
    for (const target of ['proposal', 'dev-design'] as const) {
      vi.mocked(writeFileInventory).mockClear();
      runBacktrack({
        project_root: FIXTURE_PROJECT_ROOT,
        change: 'test-change',
        phase: 'test-execution',
        backtrack_to: target,
        backtrack_reason: `回溯到 ${target}`,
      });
      expect(writeFileInventory).toHaveBeenCalledWith('/tmp/test-change', {
        written: [],
        deleted: [],
      });
    }
  });

  it('backtrack 到 implement 之后的 phase（如 test-gen / test-execution）→ 不调用 writeFileInventory（不清空，AC-6）', () => {
    for (const target of ['test-gen', 'test-execution'] as const) {
      vi.mocked(writeFileInventory).mockClear();
      runBacktrack({
        project_root: FIXTURE_PROJECT_ROOT,
        change: 'test-change',
        phase: 'test-execution',
        backtrack_to: target,
        backtrack_reason: `回溯到 ${target}`,
      });
      expect(writeFileInventory).not.toHaveBeenCalled();
    }
  });

  it('清空调用发生在 writeEvalJson 之后（执行序断言：评估条目先落盘再清清单）', () => {
    runBacktrack({
      project_root: FIXTURE_PROJECT_ROOT,
      change: 'test-change',
      phase: 'test-execution',
      backtrack_to: 'implement',
      backtrack_reason: '执行序',
    });

    expect(vi.mocked(writeEvalJson).mock.invocationCallOrder[0]).toBeLessThan(
      vi.mocked(writeFileInventory).mock.invocationCallOrder[0],
    );
  });

  it('目标 phase 恰为 implement（索引相等，≤ 判定含等号）→ 清空', () => {
    const entries: EvalEntry[] = [
      makePassEntry('proposal', 1),
      makePassEntry('dev-design', 1),
      makePassEntry('implement', 1),
      makeFailEntry('implement', 2),
    ];
    vi.mocked(readEvalJson).mockReturnValue(entries);

    runBacktrack({
      project_root: FIXTURE_PROJECT_ROOT,
      change: 'test-change',
      phase: 'implement',
      backtrack_to: 'implement',
      backtrack_reason: '重做实现',
    });

    expect(writeFileInventory).toHaveBeenCalledWith('/tmp/test-change', {
      written: [],
      deleted: [],
    });
  });

  it('test-only 工作流（phase 表无 implement）→ 不触发清空（无 writeFileInventory 调用）', () => {
    vi.mocked(getWorkflowType).mockReturnValue('test-only');
    const entries: EvalEntry[] = [
      makePassEntry('proposal', 1),
      makePassEntry('code-analyze', 1),
      makePassEntry('test-design', 1),
      makePassEntry('test-gen', 1),
      makeFailEntry('test-execution', 1),
    ];
    vi.mocked(readEvalJson).mockReturnValue(entries);

    runBacktrack({
      project_root: FIXTURE_PROJECT_ROOT,
      change: 'test-change',
      phase: 'test-execution',
      backtrack_to: 'test-gen',
      backtrack_reason: '测试需重写',
    });

    expect(readFileInventory).not.toHaveBeenCalled();
    expect(writeFileInventory).not.toHaveBeenCalled();
  });
});

// ---------------------------------------------------------------------------
// files 预检（预检先行，不部分生效）
// ---------------------------------------------------------------------------

describe('runBacktrack — files 预检（不部分生效）', () => {
  it('readFileInventory 抛「机制前旧 change 请重建」→ 整体抛错，且 readEvalJson / writeEvalJson 未被调用（评估条目不部分生效）', () => {
    vi.mocked(readFileInventory).mockImplementation(() => {
      throw new Error(
        'workflow.json 缺少 files 字段 (/tmp/test-change/workflow.json)：该 change 创建于文件清单机制之前，请重建该 change（change_create）。',
      );
    });

    expect(() =>
      runBacktrack({
        project_root: FIXTURE_PROJECT_ROOT,
        change: 'test-change',
        phase: 'test-execution',
        backtrack_to: 'implement',
        backtrack_reason: '旧 change',
      }),
    ).toThrow(/该 change 创建于文件清单机制之前，请重建/);

    expect(readEvalJson).not.toHaveBeenCalled();
    expect(writeEvalJson).not.toHaveBeenCalled();
    expect(writeFileInventory).not.toHaveBeenCalled();
  });
});

