describe('dev-team test-execution — 选项面 (AC-7)', () => {
  it('action 收到的 options 不含 mutationDiffOnly 字段（--mutation-diff-only 已删除，不残留透传）', async () => {
    const exitSpy = spyOnProcessExit();
