/**
 * 集成测试: hooks.canonical.json → buildHooksFile → 产物 PostToolUse 注册
 *
 * 以真实 hooks.canonical.json 为配置源、走真实 applyEnvTokens 展开，验证 AC-2 /
 * AC-3 的组装链语义：
 * - claude 产物 hooks.PostToolUse 含唯一 record-files 条目，matcher 含工具集与
 *   phase_next 的 MCP 全名，`__BIN:hooks__` / `__DEV_TEAM_ROOT__` token 已展开；
 * - 既有 PreToolUse 三条目与 SubagentStop 两条目的包装形态不变（回归）；
 * - cursor / cursorHome 产物因 postToolUse matcher 为 null 整段省略。
 *
 * @see openspec/changes/workflow-file-inventory/test-design.md — 集成测试「hooks.canonical.json → build 组装 → 产物 PostToolUse 注册」
 */

import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { describe, expect, it } from 'vite-plus/test';

import { getEnv } from '../../env';
import { buildHooksFile } from '../../hooks-profile';

const canonicalPath = join(
  dirname(fileURLToPath(import.meta.url)),
  '../../../hooks/hooks.canonical.json',
);

interface CommandHook {
  type: string;
  command: string;
}

interface NestedHookEntry {
  matcher: string;
  hooks: CommandHook[];
}

interface ClaudeHooks {
  hooks: {
    PreToolUse: NestedHookEntry[];
    PostToolUse: NestedHookEntry[];
    SubagentStop: NestedHookEntry[];
  };
}

interface CursorHooks {
  hooks: {
    preToolUse?: Array<{ matcher: string; command: string }>;
    postToolUse?: unknown;
    subagentStop?: unknown;
  };
}

describe('真实 canonical 组装 PostToolUse 注册', () => {
  const canonical = JSON.parse(readFileSync(canonicalPath, 'utf-8')) as object;

  it('claude：PostToolUse 唯一条目 matcher 为工具集加 phase_next MCP 全名，command 含 record-files 与已展开 token', () => {
    const parsed = JSON.parse(buildHooksFile(canonical, getEnv('claude'))) as ClaudeHooks;

    expect(parsed.hooks.PostToolUse).toHaveLength(1);
    const entry = parsed.hooks.PostToolUse[0];
    expect(entry.matcher).toBe(
      'Write|Edit|NotebookEdit|Bash|PowerShell|mcp__plugin_dev-team_dev-team__phase_next',
    );
    expect(entry.hooks).toHaveLength(1);
    const command = entry.hooks[0].command;
    expect(command).toContain('record-files');
    // `__DEV_TEAM_ROOT__` 已展开为 claude 插件根 token
    expect(command).toContain('${CLAUDE_PLUGIN_ROOT}');
    // `__BIN:hooks__` 已展开为 hooks.cjs
    expect(command).toContain('hooks.cjs');
  });

  it('claude：record-files command 无残留 __ 风格 token', () => {
    const parsed = JSON.parse(buildHooksFile(canonical, getEnv('claude'))) as ClaudeHooks;
    const command = parsed.hooks.PostToolUse[0].hooks[0].command;

    expect(command).not.toMatch(/__[A-Z]/);
    expect(command).not.toContain('__MCP:');
    expect(command).not.toContain('__BIN:');
    expect(command).not.toContain('__DEV_TEAM_ROOT__');
  });

  it('claude：既有 PreToolUse 三条目与 SubagentStop 两条目的包装形态不变（回归）', () => {
    const parsed = JSON.parse(buildHooksFile(canonical, getEnv('claude'))) as ClaudeHooks;

    expect(parsed.hooks.PreToolUse).toHaveLength(3);
    expect(parsed.hooks.PreToolUse.map((e) => e.matcher)).toEqual([
      'Write|Edit',
      'Bash',
      'PowerShell',
    ]);
    for (const entry of parsed.hooks.PreToolUse) {
      expect(entry.hooks[0].command).toContain('protect-files');
    }

    expect(parsed.hooks.SubagentStop).toHaveLength(2);
    for (const entry of parsed.hooks.SubagentStop) {
      expect(entry.hooks).toEqual([
        { type: 'command', command: expect.stringContaining('static-check') },
      ]);
    }
  });

  it('cursor / cursorHome：hooks 无 postToolUse 键（整段省略而非空数组），原始 JSON 不得出现空 postToolUse 数组', () => {
    for (const key of ['cursor', 'cursorHome'] as const) {
      const raw = buildHooksFile(canonical, getEnv(key));
      expect(raw).not.toMatch(/"postToolUse"\s*:\s*\[\s*\]/);
      const parsed = JSON.parse(raw) as CursorHooks;
      expect(Object.hasOwn(parsed.hooks, 'postToolUse')).toBe(false);
      expect(parsed.hooks.postToolUse).toBeUndefined();
    }
  });

  it('cursor：preToolUse 两条目 matchers 为 Write|StrReplace 与 Shell 且 command 含 protect-files；subagentStop 整段省略', () => {
    const parsed = JSON.parse(buildHooksFile(canonical, getEnv('cursor'))) as CursorHooks;

    expect(parsed.hooks.preToolUse).toHaveLength(2);
    expect(parsed.hooks.preToolUse!.map((e) => e.matcher)).toEqual(['Write|StrReplace', 'Shell']);
    for (const entry of parsed.hooks.preToolUse!) {
      expect(entry.command).toContain('protect-files');
    }
    // cursor 的 subagentStop matcher 均为 null，整段省略
    expect(parsed.hooks.subagentStop).toBeUndefined();
  });
});

build/__tests__/hooks-platform-subagent-.source:
/**
 * 集成测试: hooks.canonical.json → buildHooksFile → 三平台 hooks 产物
 *
 * @see openspec/changes/cursor-omit-subagent-stop/test-design.md
 */

import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { describe, expect, it } from 'vite-plus/test';

import { getEnv } from '../../env';
import { buildHooksFile } from '../../hooks-profile';

const canonicalPath = join(
  dirname(fileURLToPath(import.meta.url)),
  '../../../hooks/hooks.canonical.json',
);

describe('真实 canonical 三平台 hooks 形态', () => {
  const canonical = JSON.parse(readFileSync(canonicalPath, 'utf-8')) as {
    subagentStop: Array<{
      matchers: { claude: string; cursor: string | null };
      loop_limit?: number;
      commandTemplate: string;
    }>;
  };

  it('真实 canonical：matchers.cursor 两条均为 null', () => {
    expect(canonical.subagentStop).toHaveLength(2);
    for (const entry of canonical.subagentStop) {
      expect(entry.matchers.cursor).toBeNull();
    }
  });

  it('cursor / cursorHome：hooks 无 subagentStop 键', () => {
    for (const key of ['cursor', 'cursorHome'] as const) {
      const parsed = JSON.parse(buildHooksFile(canonical, getEnv(key))) as {
        hooks: Record<string, unknown>;
      };
      expect(Object.hasOwn(parsed.hooks, 'subagentStop')).toBe(false);
    }
  });

  it('claude：SubagentStop 含两 generator matcher 且 command 含 static-check', () => {
    const parsed = JSON.parse(buildHooksFile(canonical, getEnv('claude'))) as {
      hooks: {
        SubagentStop: Array<{ matcher: string; hooks: Array<{ command: string }> }>;
      };
    };
    expect(parsed.hooks.SubagentStop).toHaveLength(2);
    const matchers = parsed.hooks.SubagentStop.map((e) => e.matcher);
    expect(matchers).toContain('dev-team:implementation-generator');
    expect(matchers).toContain('dev-team:test-gen-generator');
    for (const entry of parsed.hooks.SubagentStop) {
      expect(entry.hooks[0]?.command).toContain('static-check');
    }
  });

  it('cursor 产物不得出现 subagentStop: []', () => {
    const raw = buildHooksFile(canonical, getEnv('cursor'));
    expect(raw).not.toMatch(/"subagentStop"\s*:\s*\[\s*\]/);
    const parsed = JSON.parse(raw) as { hooks: Record<string, unknown> };
    expect(parsed.hooks.subagentStop).toBeUndefined();
  });

  it('claude loop_limit 语义保持：canonical 为 5 且 matcher 数仍为 2', () => {
    for (const entry of canonical.subagentStop) {
      expect(entry.loop_limit).toBe(5);
    }
    const parsed = JSON.parse(buildHooksFile(canonical, getEnv('claude'))) as {
      hooks: { SubagentStop: unknown[] };
    };
    expect(parsed.hooks.SubagentStop).toHaveLength(2);
  });
});

build/apply-env-tokens.test.ts.source:
/**
 * 单元测试: apply-env-tokens.ts — 名称/路径 token 展开
 */

import { describe, expect, it } from 'vite-plus/test';

import { applyEnvTokens } from './apply-env-tokens';
import { getEnv, type ProductEnv } from './env';

describe('applyEnvTokens', () => {
  it('claude/cursor env 将 __MCP:phase_log__ 展开为插件 MCP 前缀', () => {
    for (const key of ['claude', 'cursor'] as const) {
      const env = getEnv(key);
      expect(applyEnvTokens('call __MCP:phase_log__', env)).toBe(
        'call mcp__plugin_dev-team_dev-team__phase_log',
      );
    }
  });

  it('cursorHome env 将 __MCP:phase_log__ 展开为 user MCP 前缀', () => {
    const env = getEnv('cursorHome');
    expect(applyEnvTokens('call __MCP:phase_log__', env)).toBe(
      'call mcp__user-dev-team_mcp__phase_log',
    );
  });

  it('cursorHome 展开 __SKILL: 与 __BIN: 带 dev-team_ 前缀', () => {
    const env = getEnv('cursorHome');
    expect(applyEnvTokens('__SKILL:explore__', env)).toBe('dev-team_explore');
    expect(applyEnvTokens('__BIN:mcp__', env)).toBe('dev-team_mcp.cjs');
  });

  it('plugin env 展开 __BIN:hooks__ 与 __CALL_SKILL:propose__', () => {
    const env = getEnv('cursor');
    expect(applyEnvTokens('__BIN:hooks__', env)).toBe('hooks.cjs');
    expect(applyEnvTokens('__CALL_SKILL:propose__', env)).toBe('dev-team:propose');
  });

  it('cursorHome 展开 __AGENT: 与 __CALL_AGENT: 带下划线前缀', () => {
    const env = getEnv('cursorHome');
    expect(applyEnvTokens('__AGENT:proposal-planner__', env)).toBe('dev-team_proposal-planner');
    expect(applyEnvTokens('__CALL_AGENT:proposal-planner__', env)).toBe(
      'dev-team_proposal-planner',
    );
  });

  it('plugin env 默认展开路径 token 为 contentRoot / runtimeRoot', () => {
    const env = getEnv('claude');
    const text = 'root=__DEV_TEAM_ROOT__;';
    expect(applyEnvTokens(text, env)).toBe(`root=${env.pluginRoot};`);
  });

  it('text 为 null / undefined 时抛错', () => {
    const env = getEnv('claude');
    expect(() => applyEnvTokens(null as unknown as string, env)).toThrow();
    expect(() => applyEnvTokens(undefined as unknown as string, env)).toThrow();
  });

  it('env 为 null / undefined 时抛错', () => {
    expect(() => applyEnvTokens('x', null as unknown as ProductEnv)).toThrow();
    expect(() => applyEnvTokens('x', undefined as unknown as ProductEnv)).toThrow();
  });

  it('text 为空字符串时返回空字符串', () => {
    expect(applyEnvTokens('', getEnv('claude'))).toBe('');
  });

  it('超长文本含多枚 token 时全部正确展开且不崩溃', () => {
    const env = getEnv('cursor');
    const chunk = '__SKILL:explore__ __MCP:phase_log__ __BIN:cli__ ';
    const text = chunk.repeat(80);
    expect(text.length).toBeGreaterThan(1000);
    const result = applyEnvTokens(text, env);
    expect(result).not.toContain('__SKILL:');
    expect(result).not.toContain('__MCP:');
    expect(result).not.toContain('__BIN:');
    expect(result).toContain('explore');
    expect(result).toContain('mcp__plugin_dev-team_dev-team__phase_log');
    expect(result).toContain('cli.cjs');
  });

  it('特殊字符夹杂 token 时仅替换 token、其余保留', () => {
    const env = getEnv('claude');
    const text = 'a\nb__MCP:phase_log__c\0d🙂e';
    expect(applyEnvTokens(text, env)).toBe('a\nbmcp__plugin_dev-team_dev-team__phase_logc\0d🙂e');
  });

  it('无 token 的普通字符串原样返回', () => {
    const plain = 'hello world without tokens';
    expect(applyEnvTokens(plain, getEnv('cursor'))).toBe(plain);
  });

  it('非法或残缺占位不误展开', () => {
    const env = getEnv('cursor');
    expect(applyEnvTokens('__MCP:__', env)).toBe('__MCP:__');
    expect(applyEnvTokens('__SKILL:BadId__', env)).toBe('__SKILL:BadId__');
    expect(applyEnvTokens('__AGENT:foo', env)).toBe('__AGENT:foo');
  });

  it('不发明裸服务器级 MCP 引用，仅替换合法 __MCP:<tool>__', () => {
    const env = getEnv('cursor');
    const bare = 'mcp__plugin_dev-team_dev-team__';
    expect(applyEnvTokens(bare, env)).toBe(bare);
    expect(applyEnvTokens('use __MCP:phase_log__ please', env)).toBe(
      'use mcp__plugin_dev-team_dev-team__phase_log please',
    );
  });

  it('强制展开路径 token（安装期）', () => {
    const home = getEnv('cursorHome');
    expect(applyEnvTokens('__DEV_TEAM_ROOT__/x', home)).toBe(`${home.pluginRoot}/x`);
    expect(applyEnvTokens('__DEV_TEAM_ROOT__/y', home)).toBe(`${home.pluginRoot}/y`);
  });
});

build/env.test.ts.source:
/**
 * 单元测试: env.ts — 三产物 ProductEnv 表
 */

import { describe, expect, it } from 'vite-plus/test';

import { getEnv, PRODUCT_ENV_KEYS, type ProductEnvKey } from './env';

describe('getEnv', () => {
  it('claude / cursor / cursorHome 均返回对象', () => {
    for (const key of PRODUCT_ENV_KEYS) {
      const env = getEnv(key);
      expect(env).toBeTypeOf('object');
    }
  });

  it('cursorHome 前缀与 hooks/path 阶段字段符合 home 产物约定', () => {
    const env = getEnv('cursorHome');
    expect(env.mcpToolPrefix).toBe('mcp__user-dev-team_mcp__');
    expect(env.namePrefix).toBe('dev-team_');
    expect(env.pluginPrefix).toBe('');
    expect(env.hooksFilePath).toBe('hooks.json');
  });

  it('plugin 行 mcp 前缀为现网插件前缀', () => {
    for (const key of ['claude', 'cursor'] as const) {
      const env = getEnv(key);
      expect(env.mcpToolPrefix).toBe('mcp__plugin_dev-team_dev-team__');
      expect(env.namePrefix).toBe('');
    }
  });

  it('三行 outDir 分别指向 claude-plugins / cursor-plugins / cursor-home-image 下 dev-team', () => {
    expect(getEnv('claude').outDir.replace(/\\/g, '/')).toContain('claude-plugins/dev-team');
    expect(getEnv('cursor').outDir.replace(/\\/g, '/')).toContain('cursor-plugins/dev-team');
    expect(getEnv('cursorHome').outDir.replace(/\\/g, '/')).toContain('cursor-home-image/dev-team');
  });

  it('非法 key 运行时抛错', () => {
    expect(() => getEnv('vscode' as ProductEnvKey)).toThrow(/Unknown product env key/);
  });

  it('key 为 null / undefined 时抛错', () => {
    expect(() => getEnv(null as unknown as ProductEnvKey)).toThrow();
    expect(() => getEnv(undefined as unknown as ProductEnvKey)).toThrow();
  });

  it('key 为空字符串时抛错', () => {
    expect(() => getEnv('' as ProductEnvKey)).toThrow();
  });
});
